// scripts/services/source-finder.mjs
//
// MODULE DATE: 2026-10-08 (Thursday) · v0.9.8 — "Jerome", LAYERS 1 + 2 + 3 (existence check; search a wide pool of sources, including several kinds of perspective; pick the best 3-4 and check there is enough; does it fit the category).
// Written against orchestrator.mjs / ledger-build.mjs v1.4 as uploaded to the Project 2026-10-07.
// Design: ARTICLE-PIPELINE-DESIGN-2026-10-07.md, section 4.1 and section 9. Layer 1 uses no AI and no
// network. Layer 2 calls Anthropic web search and fetches pages; it was tested with MOCKED search and
// fetch only (the build sandbox has no network) and has NEVER been run live. Treat the first live run
// as a pilot. Layer 3 (added v0.3) uses no AI and no network: it reads the pages layer 2 already fetched.
//
// WHAT THIS FILE DOES TODAY
//   Layer 1: decide whether the subject is already on the timeline.
//   Layer 2: find candidate source pages. Pass A searches ONLY the enabled allowlist domains
//            (Anthropic web search with allowed_domains). Only if the allowlist did not yield enough
//            verify-capable text (layer 3 rules: sufficiency.minWordsVerifyCapable, on
//            newSubjectMinDomains sites) does pass B search the open web. One good source can be enough.
//            PERSPECTIVE LANES (v0.5): sites have different strengths (biography, theology, Church documents,
//            primary texts, feast and devotion, an independent check). Even when the word target is met, Jerome
//            runs up to perspectives.maxExtraSearches extra allowlist searches for lanes this category should
//            have but does not yet (rules: perspectives). Lanes are Claude's starting guess; Tom edits them.
//            POOL (v0.6): Jerome keeps hunting until it has rules.selection.poolTarget substantive approved pages
//            (or hits the fetch caps), because layer 3 then picks only the best few from the pool. In rewrite mode the
//            entry's existing article links are tried first. The model only SUGGESTS URLs; code fetches
//            every page itself and records HTTP status, word count, and whether the subject's name is
//            really on the page. Pages from domains not in the registry are marked "unjudged" and are
//            never treated as proof: they wait for Ignatius (source-judge, not built) and Tom.
//   Layer 3: decide whether there is enough verify-capable material to write from, and whether the
//            subject passes the category rules (scripts/category-rules.json, editable). Output status:
//              ready          enough material, category passes: proceed to writing
//              needs_decision a person must look (unjudged pages that might make it enough, or the
//                             category rules say review: not canonized, scandal, apparition/miracle, ...)
//              too_thin       something usable was found but not enough, and nothing pending could fix it
//              not_found      nothing usable
//            SELECTION (v0.6): from everything found, layer 3 picks the best 3-4 pages (maxSelected 4): one per
//            lane in priority order first, then by score; the writer is given those, the rest are listed as
//            alsoFound. The enough-to-write check runs on the SELECTED pages: if only one qualifies, its word
//            count must pass the floor on its own.
//            ORCHESTRATOR + ARTICLE LOG (v0.9): runJerome(task, data) is the entry point for the orchestrator (task type
//            'source-find'). It runs runSourceFinder, adds Jerome's steps to article-log.json (scripts/services/article-log.mjs),
//            returns filesToCommit so the orchestrator commits the log, and stores only a compact result on the task (the
//            long per-page records stay out of workLog.json). Token use is counted by model for the cost column.
//            v0.9.8: the registry reader moved to registry.mjs (shared with ledger-build), and realFetchPage is exported so the writer (Augustine) fetches
//            Jerome's pages the very same way; nothing else changed.
//            SOURCES FILE (v0.9.7): runJerome also writes sources/<entry-id>.json (scripts/services/sources-file.mjs): the four chosen pages with
//            hashes (and full text only for registry sources Tom has set to storage "full"), the unsure pages and the verdict. This is what Augustine and
//            Thomas read.
//            AUTHORITY LOOKUP (v0.9.6): for apparitions and miracles (rules: authorityLookup) Jerome also asks which diocese judges the
//            subject and what its official website is (scripts/services/authority-finder.mjs). Code checks the page; the site goes into
//            ignatius-queue.json as "waiting" for IGNATIUS (not built) to decide. Jerome never approves a site.
//            LIVE-PILOT FIXES (v0.8, after the first real run on St. Augustine): sites that refuse automated
//            fetching (HTTP 403, e.g. britannica.com) are listed in the rules (fetchBlockedDomains) and are never
//            searched or counted; a lane can exclude paths of a site (CCEL hosts encyclopedias that are not primary
//            texts); lane picks now fill all the selected slots before score does; the result carries timing and
//            the number of web searches (for the article log and for cost).
//            ANCIENT SAINTS (v0.7): for a saint up to the year limit, "venerated" is judged by DIFFERENT KINDS of
//            evidence (Roman liturgy, early calendars, the East, early witnesses, feast, tomb and relics, church
//            dedications, patronage), counted by type, with cautions (legendary, removed from the calendar).
//            Layer 3 finds EVIDENCE (short lowercased excerpts near the subject's name) for a person to
//            look at. It cannot prove a claim, and it does NOT check that two sources agree on who the
//            person is (same dates, same facts): that is Ignatius's and Aquinas's job. Not built: Ignatius,
//            and writing sources/<entry-id>.json. Page text is held in memory for layer 3 and is never
//            put in the returned result.
//
// TWO MODES
//   mode "new"     payload { name, category?, year? }   -> existence check (exact, alt names, fuzzy)
//   mode "rewrite" task.entityId (or payload.entityId)  -> NO existence check; the caller already
//                  knows the entry, so id/name/category/year are read from data.json as given.
//
// OUTCOMES (layer 1)
//   exists          exact name, alternate name, or id matched exactly one entry. Stop: nothing to write.
//   possible_match  nothing exact, but a close name (or an ambiguous exact one) exists. A human looks
//                   at `matches` and says "same subject" or "different". Never auto-resolved either way.
//   new_subject     nothing close. Layer 2 (search) is where this goes next.
//   rewrite_ready   rewrite mode, entry found.
//   error           bad input (no name, unknown entityId).
//
// MATCHING RULES (all deterministic, see fold() and scoreMatch())
//   - Case, accents, punctuation, "St."/"Saint"/"Pope"/"Blessed", "the", "of", "and" are ignored.
//   - Roman numerals become digits and MUST agree: "Celestine I" never matches "Celestine V" at
//     the exact level, and a numeral on only one side caps the score below the confident tier.
//   - Fuzzy = best of character similarity, shared-word overlap, and "one name contained in the
//     other". Score >= 0.80 is a "fuzzy" match, 0.60-0.79 is "weak"; both yield possible_match so a
//     typo ("Agustine") or a descriptor ("Augustine of Hippo") asks a human instead of silently
//     creating a duplicate. Category is reported (categoryMatch) but never filters.
//
// RULES FILE: scripts/category-rules.json (override with CATEGORY_RULES_PATH). If it is missing, layers 1
// and 2 still run and layer 3 reports an error instead of guessing.
//
// TASK SHAPE (when the orchestrator registers it; not registered yet):
//   { id, type: 'source-finder', status: 'queued', entityId?: '<id>',
//     payload: { mode: 'new'|'rewrite', name?: 'St. Bertha', category?: 's', year?: 723 } }
//   Registering = one import + one SERVICE_HANDLERS line in orchestrator.mjs. It writes no files and
//   uses no model, so it returns { result, summary } with no filesToCommit.
//
// CLI (for testing by hand):
//   node scripts/services/source-finder.mjs "Augustine of Hippo" --category s
//   node scripts/services/source-finder.mjs --rewrite st-augustine-430
//   DATA_PATH=path/to/data.json overrides the default data.json.

import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { fileURLToPath } from 'node:url';
import { recordJerome, LOG_PATH, renderJob, loadPricing } from './article-log.mjs';
import { findAuthority, queueItemsFor, addToQueue, loadQueue, saveQueue, QUEUE_PATH } from './authority-finder.mjs';
import { buildSourcesFile, writeSourcesFile, SOURCES_DIR } from './sources-file.mjs';
import { loadRegistry, regEntry } from './registry.mjs';

const DATA_PATH = process.env.DATA_PATH || 'data.json';
const T_FUZZY = 0.8;
const T_WEAK = 0.6;
const MAX_MATCHES = 5;

// Words that carry no identity. Dropped before comparing.
const STOP = new Set(['st', 'saint', 'saints', 'sts', 'ss', 'blessed', 'bl', 'venerable', 'pope',
  'the', 'of', 'de', 'and']);

// Roman numerals that appear in papal/regnal names. Limited on purpose: a lowercase "li", "mi" or
// "di" must never be read as a number.
const ROMAN = { I: 1, II: 2, III: 3, IV: 4, V: 5, VI: 6, VII: 7, VIII: 8, IX: 9, X: 10, XI: 11,
  XII: 12, XIII: 13, XIV: 14, XV: 15, XVI: 16, XVII: 17, XVIII: 18, XIX: 19, XX: 20, XXI: 21,
  XXII: 22, XXIII: 23 };

// ---------------------------------------------------------------------------------------------
// Name folding
// ---------------------------------------------------------------------------------------------

// Accents and special letters -> plain ASCII ("Wojtyła" -> "Wojtyla"). Shared by names and page text.
function asciiFold(s) {
  return String(s == null ? '' : s)
    .replace(/[\u0141\u0142]/g, 'l').replace(/[\u00d8\u00f8]/g, 'o').replace(/[\u0110\u0111\u00d0\u00f0]/g, 'd')
    .replace(/[\u00c6\u00e6]/g, 'ae').replace(/[\u0152\u0153]/g, 'oe').replace(/\u00df/g, 'ss')
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '');
}

// -> { tokens: [..identity words..], nums: [..digit strings..], key: 'canonical comparison string' }
export function fold(s) {
  const t = asciiFold(s)
    .replace(/&/g, ' and ')
    .replace(/['\u2019`]s\b/g, '')
    .replace(/[^A-Za-z0-9]+/g, ' ')
    .trim();
  const raw = t ? t.split(/\s+/) : [];
  const tokens = [];
  const nums = [];
  raw.forEach((w, i) => {
    const up = w.toUpperCase();
    const isLast = i === raw.length - 1;
    // Uppercase anywhere ("John Paul II"), or any case as the last word of a 2+ word name
    // ("celestine i"), and only for the listed numerals.
    if (ROMAN[up] && (w === up || (isLast && raw.length >= 2))) { nums.push(String(ROMAN[up])); return; }
    const lw = w.toLowerCase();
    if (/^\d+$/.test(lw)) { nums.push(String(parseInt(lw, 10))); return; }
    if (STOP.has(lw)) return;
    tokens.push(lw);
  });
  return { tokens, nums, key: tokens.join(' ') + (nums.length ? ' #' + nums.join('.') : '') };
}

// ---------------------------------------------------------------------------------------------
// Similarity
// ---------------------------------------------------------------------------------------------

function lev(a, b) {
  if (a === b) return 0;
  if (!a.length) return b.length;
  if (!b.length) return a.length;
  let prev = Array.from({ length: b.length + 1 }, (_, i) => i);
  for (let i = 1; i <= a.length; i++) {
    const cur = [i];
    for (let j = 1; j <= b.length; j++) {
      cur[j] = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
    }
    prev = cur;
  }
  return prev[b.length];
}

const sameNums = (a, b) => a.length === b.length && a.every((x, i) => x === b[i]);

// 0..1. q and e are fold() results (query, entry-name).
export function scoreMatch(q, e) {
  const qs = q.tokens.join(' ');
  const es = e.tokens.join(' ');
  if (!qs || !es) return 0;
  const sq = new Set(q.tokens);
  const se = new Set(e.tokens);
  const inter = [...sq].filter(x => se.has(x)).length;
  const dice = (2 * inter) / (sq.size + se.size);
  const levr = 1 - lev(qs, es) / Math.max(qs.length, es.length);
  let cont = 0;
  if (inter > 0) {
    if (inter === se.size) cont = se.size >= 2 ? 0.85 : 0.7;        // whole entry name sits inside the query
    else if (inter === sq.size) cont = sq.size >= 2 ? 0.85 : 0.6;   // whole query sits inside the entry name
  }
  let score = Math.max(dice, levr, cont);
  // Numerals are identity: "Celestine I" is not "Celestine V".
  if (q.nums.length && e.nums.length && !sameNums(q.nums, e.nums)) score = Math.min(score, 0.5);
  else if (q.nums.length !== e.nums.length && (q.nums.length === 0 || e.nums.length === 0)) score = Math.min(score, 0.79);
  return score;
}

// ---------------------------------------------------------------------------------------------
// Existence check
// ---------------------------------------------------------------------------------------------

const brief = (e, level, score, via) => ({
  id: e.id, name: e.n, category: e.t || null, year: e.y == null ? null : e.y, region: e.r || null,
  level, score: Math.round(score * 100) / 100, via: via || null
});

// entries: data.json entries array. opts: { category, year }.
// Returns { level, matches[], ... } where level is exact|alt|id|fuzzy|weak|none.
export function checkExistence(name, entries, opts = {}) {
  const q = fold(name);
  if (!q.tokens.length && !q.nums.length) return { level: 'none', matches: [], note: 'name has no usable words' };
  const qSlug = String(name || '').trim().toLowerCase();
  const exact = [];
  const alt = [];
  const byId = [];
  const scored = [];

  for (const e of entries || []) {
    if (!e || !e.id) continue;
    if (qSlug && e.id.toLowerCase() === qSlug) { byId.push(brief(e, 'id', 1, 'id')); continue; }
    const en = fold(e.n);
    if (en.key && en.key === q.key) { exact.push(brief(e, 'exact', 1, e.n)); continue; }
    let altHit = null;
    for (const a of (Array.isArray(e.alt) ? e.alt : [])) {
      const af = fold(a);
      if (af.key && af.key === q.key) { altHit = a; break; }
    }
    if (altHit) { alt.push(brief(e, 'alt', 1, altHit)); continue; }
    // Fuzzy: best score over the display name and every alternate name.
    let best = scoreMatch(q, en);
    let via = e.n;
    for (const a of (Array.isArray(e.alt) ? e.alt : [])) {
      const s = scoreMatch(q, fold(a));
      if (s > best) { best = s; via = a; }
    }
    if (best >= T_WEAK) scored.push(brief(e, best >= T_FUZZY ? 'fuzzy' : 'weak', best, via));
  }

  const decorate = list => list.map(m => ({
    ...m,
    categoryMatch: opts.category ? m.category === opts.category : null,
    yearDelta: (opts.year != null && m.year != null) ? Math.abs(Number(opts.year) - m.year) : null
  }));

  scored.sort((a, b) => b.score - a.score);
  const hard = [...byId, ...exact, ...alt];
  if (hard.length) {
    const level = byId.length ? 'id' : exact.length ? 'exact' : 'alt';
    return { level, matches: decorate(hard.concat(scored).slice(0, MAX_MATCHES)), ambiguous: hard.length > 1 };
  }
  if (scored.length) {
    const level = scored[0].level; // fuzzy or weak
    return { level, matches: decorate(scored.slice(0, MAX_MATCHES)), ambiguous: false };
  }
  return { level: 'none', matches: [], ambiguous: false };
}

// ---------------------------------------------------------------------------------------------
// Subject resolution (both modes)
// ---------------------------------------------------------------------------------------------

export function findSubject(input, dataJson) {
  const entries = (dataJson && dataJson.entries) || [];
  const mode = input.mode === 'rewrite' || (!input.mode && input.entityId && !input.name) ? 'rewrite' : 'new';
  const note = 'Layer 1 result (who the subject is). Sources are searched and assessed in layers 2-3 whenever search is on; see the search and layer3 fields.';

  if (mode === 'rewrite') {
    const id = input.entityId;
    if (!id) return { outcome: 'error', mode, reason: 'rewrite mode needs an entityId' };
    const e = entries.find(x => x.id === id);
    if (!e) return { outcome: 'error', mode, reason: 'no entry with id ' + id };
    return {
      outcome: 'rewrite_ready', mode,
      subject: { id: e.id, name: e.n, category: e.t || null, year: e.y == null ? null : e.y, region: e.r || null,
        hasArticle: !!(e.art && Array.isArray(e.art.sections) && e.art.sections.length) },
      note
    };
  }

  const name = String(input.name || '').trim();
  if (!name) return { outcome: 'error', mode, reason: 'new mode needs a name' };
  const subject = { name, category: input.category || null, year: input.year == null ? null : Number(input.year) };
  const chk = checkExistence(name, entries, subject);

  if (chk.level === 'exact' || chk.level === 'alt' || chk.level === 'id') {
    if (chk.ambiguous && subject.category) {
      // The caller said what kind of thing this is; if that picks exactly one exact match, use it.
      const hard = chk.matches.filter(m => m.level === chk.level);
      const same = hard.filter(m => m.categoryMatch === true);
      if (same.length === 1) {
        return { outcome: 'exists', mode, subject, level: chk.level, match: same[0], matches: chk.matches,
          note: 'several entries share this name; the category picked one' };
      }
    }
    if (chk.ambiguous) {
      return { outcome: 'possible_match', mode, subject, level: chk.level, matches: chk.matches,
        reason: 'more than one entry matches this name exactly; a human must pick' };
    }
    return { outcome: 'exists', mode, subject, level: chk.level, match: chk.matches[0], matches: chk.matches };
  }
  if (chk.level === 'fuzzy' || chk.level === 'weak') {
    return { outcome: 'possible_match', mode, subject, level: chk.level, matches: chk.matches,
      reason: chk.level === 'fuzzy' ? 'a very similar name is already on the timeline'
        : 'a partly similar name is already on the timeline' };
  }
  return { outcome: 'new_subject', mode, subject, matches: [], note };
}

// ---------------------------------------------------------------------------------------------
// LAYER 2 — find candidate sources
// ---------------------------------------------------------------------------------------------

const CACHE_DIR = process.env.SOURCE_CACHE_DIR || '.cache/source-finder';
const MIN_ALLOWLIST_SOURCES = 2;   // FALLBACK only (used when no layer 3 rules are given): fewer usable allowlisted pages than this -> widen to the open web
const MAX_FETCH_PER_PASS = 8;
const MAX_SEARCHES = 3;
const FETCH_TIMEOUT_MS = 20000;
const FETCH_GAP_MS = 600;          // minimum gap between requests to the same host
const MAX_PAGE_CHARS = 600000;
const FINDER_MODEL = { provider: 'anthropic', modelId: 'claude-sonnet-4-6' };

const CATEGORY_LABEL = { s: 'saint', c: 'ecumenical council', p: 'persecution of Christians',
  m: 'Marian apparition', u: 'Eucharistic miracle', e: 'event in the history of the Catholic Church' };

// Never fetched, even in the open-web pass (the registry rules: no Wikipedia or mirrors, blogs, forums,
// social media). Hosts match with all their subdomains.
const NEVER_HOSTS = ['wikipedia.org', 'wikimedia.org', 'wikiwand.com', 'dbpedia.org', 'reddit.com', 'quora.com',
  'facebook.com', 'instagram.com', 'x.com', 'twitter.com', 'tiktok.com', 'pinterest.com', 'youtube.com',
  'youtu.be', 'medium.com', 'substack.com', 'blogspot.com', 'wordpress.com', 'tumblr.com', 'linkedin.com'];

let tokensUsed = 0;
// This run's search-call tokens, for the cost column. input = NEW input as the API reports it (cache reads and writes are separate).
// Requests whose whole prompt (input + cache read + cache write) is over LONG_PROMPT_TOKENS go in `long`, because some models
// (Haiku 5.5) charge a higher price for those. The bucket split is harmless for models that do not.
const LONG_PROMPT_TOKENS = 100000;
export const newTally = () => ({ input: 0, output: 0, cacheRead: 0, cacheWrite: 0, long: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 } });
let usageTally = newTally();
let authoritySearches = 0;   // web searches spent on the diocese lookup, added to the run's total
export function addUsage(t, u) {
  const i = (u && u.input_tokens) || 0, o = (u && u.output_tokens) || 0, cr = (u && u.cache_read_input_tokens) || 0, cw = (u && u.cache_creation_input_tokens) || 0;
  const b = (i + cr + cw) > LONG_PROMPT_TOKENS ? t.long : t;
  b.input += i; b.output += o; b.cacheRead += cr; b.cacheWrite += cw;
}
const lastHit = new Map();
const sleep = ms => new Promise(r => setTimeout(r, ms));
const wordCount = s => String(s || '').trim().split(/\s+/).filter(Boolean).length;
const hostMatches = (h, list) => list.some(d => h === d || h.endsWith('.' + d));

// The registry reader lives in registry.mjs, shared with ledger-build (Thomas), so both always agree on which sites count.
export { loadRegistry, regEntry };

// https only, a real hostname, no IPs, no localhost, no credentials, no fragment.
export function safeUrl(raw) {
  let u;
  try { u = new URL(String(raw || '').trim()); } catch (_e) { return null; }
  if (u.protocol !== 'https:' || u.username || u.password) return null;
  const h = u.hostname.toLowerCase();
  if (!h.includes('.') || /^\d+(\.\d+){3}$/.test(h) || h.includes(':') || h === 'localhost' || h.endsWith('.local') || h.endsWith('.internal')) return null;
  u.hash = '';
  return u.toString();
}

// Domains the search is restricted to in pass A: enabled, and not Scripture (a Bible text says nothing about a saint's life).
export function allowedDomains(reg) {
  return reg.domains.filter(e => e.enabled !== false && e.tier !== 'scripture').map(e => e.domain);
}

// ---- text utilities (copied from ledger-build so each service stands alone) ----
const ENT = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', mdash: '\u2014', ndash: '\u2013',
  rsquo: '\u2019', lsquo: '\u2018', ldquo: '\u201c', rdquo: '\u201d', hellip: '\u2026', eacute: '\u00e9',
  egrave: '\u00e8', agrave: '\u00e0', ouml: '\u00f6', uuml: '\u00fc', auml: '\u00e4', ccedil: '\u00e7' };
function decodeEntities(s) {
  return String(s || '')
    .replace(/&#x([0-9a-f]+);/gi, (_m, h) => { try { return String.fromCodePoint(parseInt(h, 16)); } catch (_e) { return ' '; } })
    .replace(/&#(\d+);/g, (_m, d) => { try { return String.fromCodePoint(parseInt(d, 10)); } catch (_e) { return ' '; } })
    .replace(/&([a-z]+);/gi, (m, n) => (n.toLowerCase() in ENT ? ENT[n.toLowerCase()] : m));
}
function htmlToText(html) {
  let t = String(html || '')
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<(script|style|noscript|svg)\b[\s\S]*?<\/\1>/gi, ' ')
    .replace(/<\/(p|div|li|h[1-6]|tr|blockquote|section|article)>/gi, '\n')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<[^>]+>/g, ' ');
  t = decodeEntities(t);
  return t.split('\n').map(l => l.replace(/\s+/g, ' ').trim()).filter(Boolean).join('\n');
}
const plainWords = s => asciiFold(s).toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();

// ---- page fetch (real) ----
export async function realFetchPage(url) {
  const cp = CACHE_DIR + '/' + createHash('sha1').update(url).digest('hex') + '.json';
  try { if (existsSync(cp)) { const c = JSON.parse(readFileSync(cp, 'utf8')); if (c && c.ok && c.text) return c; } } catch (_e) { /* refetch */ }
  const host = new URL(url).hostname.toLowerCase();
  try {
    const wait = (lastHit.get(host) || 0) + FETCH_GAP_MS - Date.now();
    if (wait > 0) await sleep(wait);
    lastHit.set(host, Date.now());
    const res = await fetch(url, {
      redirect: 'follow', signal: AbortSignal.timeout(FETCH_TIMEOUT_MS),
      headers: { 'User-Agent': 'CatholicTimelineSourceBot/1.0 (+https://catholictimeline.org)', 'Accept': 'text/html,text/plain;q=0.9' }
    });
    if (res.status !== 200) return { url, ok: false, http: res.status, text: '', note: 'HTTP ' + res.status };
    const ctype = res.headers.get('content-type') || '';
    if (!/html|text\/plain|xml/i.test(ctype)) return { url, ok: false, http: 200, text: '', note: 'not a text page (' + ctype.slice(0, 40) + ')' };
    const buf = Buffer.from(await res.arrayBuffer());
    let charset = (/charset=([\w-]+)/i.exec(ctype) || [])[1];
    if (!charset) charset = (/<meta[^>]+charset=["']?([\w-]+)/i.exec(buf.subarray(0, 4096).toString('latin1')) || [])[1];
    let html;
    try { html = new TextDecoder(charset || 'utf-8').decode(buf); } catch (_e) { html = buf.toString('utf8'); }
    const text = htmlToText(html).slice(0, MAX_PAGE_CHARS);
    if (text.length < 200) return { url, ok: false, http: 200, text: '', note: 'page has almost no text (may need JavaScript)' };
    const out = { url, ok: true, http: 200, text, note: '' };
    try { mkdirSync(CACHE_DIR, { recursive: true }); writeFileSync(cp, JSON.stringify(out)); } catch (_e) { /* cache is optional */ }
    return out;
  } catch (err) {
    return { url, ok: false, http: 0, text: '', note: 'fetch failed: ' + String((err && err.message) || err).slice(0, 120) };
  }
}

// ---- web search (real): Anthropic web_search; URLs are harvested from the tool-result blocks, not from the
// model's prose, so nothing the model merely says can become a candidate. ----
async function realSearch({ query, allowedDomains, model, maxUses }) {
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) throw new Error('Missing ANTHROPIC_API_KEY secret (needed for source search).');
  const tool = { type: 'web_search_20250305', name: 'web_search', max_uses: maxUses || MAX_SEARCHES };
  if (allowedDomains && allowedDomains.length) tool.allowed_domains = allowedDomains;
  const body = {
    model: model || FINDER_MODEL.modelId, max_tokens: 2000, tools: [tool],
    system: 'You locate web pages. Always use the search tool; never answer from memory. Search with different wording each time. Reply with one short line saying what you searched.',
    messages: [{ role: 'user', content: query }]
  };
  const res = await fetch('https://api.anthropic.com/v1/messages', {
    method: 'POST', headers: { 'x-api-key': apiKey, 'anthropic-version': '2023-06-01', 'Content-Type': 'application/json' },
    body: JSON.stringify(body)
  });
  if (!res.ok) {
    const err = new Error('Anthropic search ' + res.status + ': ' + String(await res.text().catch(() => '')).slice(0, 300));
    err.status = res.status;
    if (res.status === 429 || /quota|credit|billing/i.test(err.message)) err.deferred = true;
    throw err;
  }
  const data = await res.json();
  tokensUsed += ((data.usage && data.usage.input_tokens) || 0) + ((data.usage && data.usage.output_tokens) || 0);
  addUsage(usageTally, data.usage);
  const results = [];
  let searches = 0;
  for (const b of data.content || []) {
    if (b.type === 'server_tool_use') searches++;
    if (b.type === 'web_search_tool_result' && Array.isArray(b.content)) {
      for (const r of b.content) if (r && r.type === 'web_search_result' && r.url) results.push({ url: r.url, title: r.title || '' });
    }
  }
  return { results, searches };
}

// ---- one question to the model with web search, answered in text (used for the diocese lookup). The model's words are only ever
// parsed and then CHECKED by code (the page is fetched and read); nothing it says is trusted on its own. ----
async function realAsk({ prompt, maxUses, model }) {
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) throw new Error('Missing ANTHROPIC_API_KEY secret (needed for the diocese lookup).');
  const body = {
    model: model || FINDER_MODEL.modelId, max_tokens: 1500,
    tools: [{ type: 'web_search_20250305', name: 'web_search', max_uses: maxUses || 2 }],
    system: 'You research facts with the search tool and never answer from memory. Reply only in the format you are asked for.',
    messages: [{ role: 'user', content: prompt }]
  };
  const res = await fetch('https://api.anthropic.com/v1/messages', {
    method: 'POST', headers: { 'x-api-key': apiKey, 'anthropic-version': '2023-06-01', 'Content-Type': 'application/json' }, body: JSON.stringify(body)
  });
  if (!res.ok) {
    const err = new Error('Anthropic ask ' + res.status + ': ' + String(await res.text().catch(() => '')).slice(0, 300));
    err.status = res.status;
    if (res.status === 429 || /quota|credit|billing/i.test(err.message)) err.deferred = true;
    throw err;
  }
  const data = await res.json();
  tokensUsed += ((data.usage && data.usage.input_tokens) || 0) + ((data.usage && data.usage.output_tokens) || 0);
  addUsage(usageTally, data.usage);
  let searches = 0;
  for (const b of data.content || []) if (b.type === 'server_tool_use') searches++;
  const text = (data.content || []).filter(b => b.type === 'text').map(b => b.text || '').join('\n').trim();
  return { text, searches };
}

// ---- classify + fetch one candidate ----
// status: approved (enabled in the registry) | unjudged (domain not in the registry; waits for Ignatius)
//       | disabled (registry says off; not fetched) | blocked (never-allowed host; not fetched)
export async function examine(cand, subject, reg, deps) {
  const url = safeUrl(cand.url);
  if (!url) return { url: String(cand.url), status: 'blocked', usable: false, note: 'not a plain https page on a real host' };
  const host = new URL(url).hostname.toLowerCase();
  const out = { url, title: cand.title || '', domain: host, via: cand.via || null };
  if (hostMatches(host, NEVER_HOSTS)) return { ...out, status: 'blocked', usable: false, note: 'a never-allowed kind of site' };
  const e = regEntry(reg, host);
  if (e && e.enabled === false) return { ...out, status: 'disabled', tier: e.tier, usable: false, note: 'listed in the registry but not enabled' };
  out.status = e ? 'approved' : 'unjudged';
  if (e) { out.tier = e.tier; out.canVerify = !(reg.tiers[e.tier] && reg.tiers[e.tier].canVerify === false); }

  const f = await deps.fetchPage(url);
  out.http = f.http;
  if (!f.ok) return { ...out, usable: false, note: f.note || 'fetch failed' };

  const text = plainWords(f.text);
  const toks = fold(subject.name).tokens;
  const need = toks.length > 3 ? Math.ceil(toks.length * 0.75) : toks.length;
  const hits = toks.filter(t => new RegExp('\\b' + t + '\\b').test(text)).length;
  const lead = toks.slice().sort((a, b) => b.length - a.length)[0];
  out.words = wordCount(f.text);
  out.fetchedAt = new Date().toISOString();
  out.hash = createHash('sha256').update(f.text).digest('hex').slice(0, 16);
  out.namePresent = toks.length ? hits >= need : null;
  out.mentions = lead ? (text.match(new RegExp('\\b' + lead + '\\b', 'g')) || []).length : 0;
  out.titleHasName = toks.length ? toks.every(t => plainWords(cand.title || '').split(' ').includes(t)) : false;
  out.usable = !!out.namePresent;
  if (!out.usable) out.note = 'the subject\'s name does not appear on the page';
  // Page text for layer 3: in memory only (non-enumerable, so it never reaches JSON, logs or the result).
  Object.defineProperty(out, 'text', { value: asciiFold(f.text).toLowerCase().replace(/\s+/g, ' '), enumerable: false });
  Object.defineProperty(out, 'plain', { value: f.text, enumerable: false });     // original-case text: written to sources/<id>.json ONLY for registry sources set to storage "full"
  return out;
}

const queryFor = (subject, variant, lane) => {
  const label = CATEGORY_LABEL[subject.category] || 'subject';
  if (variant === 'lane') return 'Find pages ' + lane.ask + ' this ' + label + ' in Catholic history: "' + subject.name + '"' +
    (subject.year != null ? ' (around the year ' + subject.year + ')' : '') + '.';
  if (variant === 'more') return 'Find additional in-depth pages about this ' + label + ' in Catholic history: "' + subject.name + '"' +
    (subject.year != null ? ' (around the year ' + subject.year + ')' : '') + '. Look for the full life or history, sources, and primary texts, not short summaries.';
  return 'Find web pages that give a substantial account of this ' + label + ' in Catholic history: "' + subject.name + '"' +
    (subject.year != null ? ' (around the year ' + subject.year + ')' : '') + '. Prefer reference works, official Church sources and long-form biographies.';
};

// ---------------------------------------------------------------------------------------------
// Perspective lanes (Tom's rule: different sites have different strengths; gather several kinds)
// ---------------------------------------------------------------------------------------------

const siteSpec = x => (typeof x === 'string' ? { domain: x } : x);

// Which lane does this URL belong to? A site with a pathPrefix is more specific than a whole-domain site,
// so path matches are tried first. A page belongs to at most one lane.
export function laneOf(url, lanes) {
  let u;
  try { u = new URL(url); } catch (_e) { return null; }
  const host = u.hostname.toLowerCase();
  const hostOk = d => host === d || host.endsWith('.' + d);
  const excluded = x => (x.exclude || []).some(pre => u.pathname.startsWith(pre));   // parts of a site that are NOT this kind of page
  for (const lane of lanes) for (const raw of lane.sites || []) { const x = siteSpec(raw); if (x.pathPrefix && hostOk(x.domain) && u.pathname.startsWith(x.pathPrefix) && !excluded(x)) return lane.id; }
  for (const lane of lanes) for (const raw of lane.sites || []) { const x = siteSpec(raw); if (!x.pathPrefix && hostOk(x.domain) && !excluded(x)) return lane.id; }
  return null;
}

// The lanes this category should have, in priority order; null when the rules define none (feature off).
export function perspectivePlan(rules, category) {
  const p = rules && rules.perspectives;
  if (!p || p.enabled === false || !p.lanes) return null;
  const order = (p.byCategory && p.byCategory[category]) || [];
  const blocked = (rules.fetchBlockedDomains || []).map(d => String(d).toLowerCase());
  const isBlocked = d => blocked.some(b => d === b || d.endsWith('.' + b));
  // a lane whose every site refuses automated fetching can never be filled: leave it out instead of wasting searches on it
  const lanes = order.filter(id => p.lanes[id]).map(id => ({ id, ...p.lanes[id] }))
    .filter(l => (l.sites || []).some(raw => !isBlocked(siteSpec(raw).domain.toLowerCase())));
  if (!lanes.length) return null;
  return { lanes, maxExtraSearches: p.maxExtraSearches == null ? 2 : p.maxExtraSearches, maxFetchPerLane: p.maxFetchPerLane || 4,
    minWords: p.minWordsPerLane == null ? 300 : p.minWordsPerLane, minMentions: p.minMentionsPerLane == null ? 1 : p.minMentionsPerLane,
    minLanesForRich: p.minLanesForRich == null ? 3 : p.minLanesForRich,
    searchesPerLane: p.searchesPerLane || 1 };
}

// Words gathered per lane from approved, usable pages that are really about the subject. A normal lane needs
// verify-capable pages; a contextOnly lane accepts any approved page (it adds perspective, never proof).
export function laneCoverage(sources, plan) {
  const cov = {};
  for (const lane of plan.lanes) cov[lane.id] = { id: lane.id, label: lane.label, contextOnly: !!lane.contextOnly, words: 0, pages: 0 };
  for (const s of sources || []) {
    if (!s.usable || s.status !== 'approved') continue;
    const id = laneOf(s.url, plan.lanes);
    if (!id) continue;
    const lane = plan.lanes.find(l => l.id === id);
    if (!lane.contextOnly && !s.canVerify) continue;
    if ((s.mentions || 0) < plan.minMentions) continue;
    cov[id].words += s.words || 0;
    cov[id].pages += 1;
  }
  for (const id of Object.keys(cov)) cov[id].covered = cov[id].words >= plan.minWords;
  return cov;
}

// The enabled registry domains behind a lane (searches are restricted to these).
function laneDomains(lane, reg, isBlocked = () => false) {
  const out = new Set();
  for (const raw of lane.sites || []) {
    const x = siteSpec(raw);
    const e = regEntry(reg, x.domain);
    if (e && e.enabled !== false && e.tier !== 'scripture' && !isBlocked(x.domain)) out.add(x.domain);
  }
  return [...out];
}


// subject: { name, category, year, links?[] }.  opts: { allowlistOnly, minWords?, targetWords?, minMentions?, minDomains?, perspectives?, poolTarget?, blockedDomains?, model }.
// From the layer 3 rules: minWords = floor (enough to write from; below it the open web is searched too),
// targetWords = plenty (below it a second allowlist search runs), minMentions = how often the name must appear
// for a page to count as substantive. Without minWords the old "MIN_ALLOWLIST_SOURCES usable pages" rule applies.
// deps (all optional, for tests): { registry, search({query, allowedDomains}), fetchPage(url) }.
export async function findSources(subject, opts = {}, deps = {}) {
  const reg = deps.registry || loadRegistry();
  const d = { fetchPage: deps.fetchPage || realFetchPage, search: deps.search || realSearch };
  const seen = new Set();
  const sources = [];
  const passes = [];

  const runPass = async (kind, cands, note, maxFetch = MAX_FETCH_PER_PASS) => {
    const fresh = [];
    for (const c of cands) {
      const u = safeUrl(c.url) || String(c.url);
      if (seen.has(u)) continue;
      seen.add(u);
      fresh.push(c);
    }
    let fetched = 0;
    const got = [];
    for (const c of fresh) {
      const url = safeUrl(c.url);
      const needsFetch = url && !hostMatches(new URL(url).hostname.toLowerCase(), NEVER_HOSTS);
      if (needsFetch && fetched >= maxFetch) { got.push({ url: c.url, status: 'skipped', usable: false, note: 'fetch limit for this pass reached' }); continue; }
      const ex = await examine({ ...c, via: kind }, subject, reg, d);
      if (ex.http !== undefined) fetched++;
      got.push(ex);
    }
    sources.push(...got);
    passes.push({ kind, note, seen: fresh.length, fetched, usable: got.filter(g => g.usable).length });
  };
  const usableApproved = () => sources.filter(s => s.usable && s.status === 'approved').length;
  // SUBSTANTIVE material = a page on an approved, verify-capable site that is really about the subject
  // (the name appears at least opts.minMentions times), not a passing mention. Layer 3 rules decide the
  // numbers; without them (opts.minWords unset) the old "MIN_ALLOWLIST_SOURCES usable pages" rule applies.
  const substantivePages = () => sources.filter(s => s.usable && s.status === 'approved' && s.canVerify && (s.mentions || 0) >= (opts.minMentions || 0));
  const subWords = () => substantivePages().reduce((n, s) => n + (s.words || 0), 0);
  const sitesOk = () => new Set(substantivePages().map(s => baseDomain(s.domain))).size >= (opts.minDomains || 1);
  // enough = the floor (enough to write from); rich = the target (plenty to write from).
  const enoughApproved = () => opts.minWords == null ? usableApproved() >= MIN_ALLOWLIST_SOURCES : (subWords() >= opts.minWords && sitesOk());
  const poolCount = () => sources.filter(s => s.usable && s.status === 'approved' && (s.mentions || 0) >= (opts.minMentions || 0)).length;
  const richApproved = () => opts.targetWords == null ? enoughApproved() : (subWords() >= opts.targetWords && sitesOk() && poolCount() >= (opts.poolTarget || 0));

  // Sites that refuse automated fetching (HTTP 403) are never searched; a search that includes them only wastes fetches.
  const blockedList = (opts.blockedDomains || []).map(x => String(x).toLowerCase());
  const isBlocked = dm => blockedList.some(b => dm === b || dm.endsWith('.' + b));
  const allowed = () => allowedDomains(reg).filter(dm => !isBlocked(dm.toLowerCase()));
  let webSearches = 0, searchCalls = 0;
  const countSearch = r => { searchCalls++; webSearches += (r && r.searches) || 0; return r; };

  // Pass 0 (rewrite only): the links the article already cites.
  if (Array.isArray(subject.links) && subject.links.length) {
    await runPass('existing-links', subject.links.map(u => ({ url: typeof u === 'string' ? u : u.url, title: typeof u === 'string' ? '' : (u.label || '') })), 'links already in the article');
  }
  // Pass A: allowlist only.
  if (!richApproved()) {
    const r = countSearch(await d.search({ query: queryFor(subject), allowedDomains: allowed(), model: opts.model }));
    await runPass('allowlist', r.results, 'search restricted to ' + allowed().length + ' enabled domains (' + (r.searches || 0) + ' searches)');
  }
  // Pass A2: still short of the TARGET (plenty of material)? One more allowlist search, worded differently,
  // so thin pages do not stop the hunt while better pages are still out there. Only runs when a target is set.
  if (opts.targetWords != null && !richApproved()) {
    const r = countSearch(await d.search({ query: queryFor(subject, 'more'), allowedDomains: allowed(), model: opts.model }));
    await runPass('allowlist-more', r.results, 'second allowlist search, different wording (' + (r.searches || 0) + ' searches); substantive words so far ' + subWords());
  }
  // Lane passes (v0.5): the word target says nothing about VARIETY. For each lane this category should have but
  // does not yet (in priority order, at most maxExtraSearches in all), one allowlist search restricted to that
  // lane's sites. Runs even when the target is already met, and in rewrite mode too.
  if (opts.perspectives) {
    const plan = opts.perspectives;
    let used = 0;
    for (const lane of plan.lanes) {
      if (used >= plan.maxExtraSearches) break;
      if (laneCoverage(sources, plan)[lane.id].covered) continue;
      const doms = laneDomains(lane, reg, dm => isBlocked(dm.toLowerCase()));
      if (!doms.length) continue;
      used++;
      const r = countSearch(await d.search({ query: queryFor(subject, 'lane', lane), allowedDomains: doms, model: opts.model, maxUses: plan.searchesPerLane }));
      await runPass('lane:' + lane.id, r.results, 'perspective search: ' + lane.label + ' (' + doms.length + ' sites; ' + (r.searches || 0) + ' searches)', plan.maxFetchPerLane);
    }
  }
  // Pass B: open web, only when the allowlist came up short.
  let widened = false;
  if (!enoughApproved() && !opts.allowlistOnly) {
    widened = true;
    const r = countSearch(await d.search({ query: queryFor(subject), allowedDomains: null, model: opts.model }));
    await runPass('open-web', r.results, 'open web (' + (r.searches || 0) + ' searches); new domains are unjudged until Ignatius and Tom decide');
  }

  const counts = {
    usableApproved: usableApproved(),
    usableUnjudged: sources.filter(s => s.usable && s.status === 'unjudged').length,
    unusable: sources.filter(s => !s.usable).length,
    totalWordsUsable: sources.filter(s => s.usable).reduce((n, s) => n + (s.words || 0), 0)
  };
  return { widened, passes, counts, webSearches, searchCalls, sources };
}

// ---------------------------------------------------------------------------------------------
// Selection: from the whole pool, the best few pages (Tom's rule: search wide, provide the best 3-4)
// ---------------------------------------------------------------------------------------------

export function selectSources(sources, rules, category) {
  const cfg = rules.selection || {};
  const maxSel = cfg.maxSelected || 4, maxDom = cfg.maxPerDomain || 2, maxCtx = cfg.maxContextOnly == null ? 1 : cfg.maxContextOnly;
  const W = cfg.weights || { words: 40, mentions: 30, titleHasName: 10 };
  const tw = cfg.tierWeight || {};
  const plan = perspectivePlan(rules, category);
  const minM = plan ? plan.minMentions : 1;
  const score = s => Math.round(((Math.min(s.words || 0, cfg.maxWordsCredited || 6000) / (cfg.maxWordsCredited || 6000)) * (W.words || 0) +
    (Math.min(s.mentions || 0, cfg.maxMentionsCredited || 20) / (cfg.maxMentionsCredited || 20)) * (W.mentions || 0) +
    (s.titleHasName ? (W.titleHasName || 0) : 0) + (tw[s.tier] || 0)) * 10) / 10;
  const cands = (sources || [])
    .filter(s => s.usable && s.status === 'approved' && (s.mentions || 0) >= minM)
    .map(s => ({ s, lane: plan ? laneOf(s.url, plan.lanes) : null, score: score(s) }))
    .sort((a, b) => b.score - a.score);
  const picks = [], dom = {};
  let ctx = 0;
  const can = c => picks.length < maxSel && !picks.includes(c) && (dom[baseDomain(c.s.domain)] || 0) < maxDom && (c.s.canVerify || ctx < maxCtx);
  const add = c => { picks.push(c); dom[baseDomain(c.s.domain)] = (dom[baseDomain(c.s.domain)] || 0) + 1; if (!c.s.canVerify) ctx++; };
  if (plan) for (const lane of plan.lanes) {            // one per lane, best first, in the category's priority order
    if (picks.length >= maxSel) break;
    const c = cands.find(x => x.lane === lane.id && can(x));
    if (c) add(c);
  }
  for (const c of cands) if (can(c)) add(c);
  if (!picks.some(c => c.s.canVerify)) {                // never hand over context only
    const v = cands.find(c => c.s.canVerify);
    if (v) { picks.sort((a, b) => a.score - b.score); if (picks.length >= maxSel) picks[0] = v; else picks.push(v); }
  }
  picks.sort((a, b) => b.score - a.score);
  const brief = c => ({ url: c.s.url, title: c.s.title, domain: c.s.domain, tier: c.s.tier, lane: c.lane, canVerify: !!c.s.canVerify,
    words: c.s.words, mentions: c.s.mentions, score: c.score });
  return { picked: picks.map(c => c.s), selected: picks.map(brief),
    alsoFound: cands.filter(c => !picks.includes(c)).map(c => ({ url: c.s.url, domain: c.s.domain, lane: c.lane, words: c.s.words, score: c.score })) };
}

// ---------------------------------------------------------------------------------------------
// LAYER 3 — is there enough to write from, and does the subject fit its category?
// No AI, no network. Reads the pages layer 2 fetched and scripts/category-rules.json.
// ---------------------------------------------------------------------------------------------

const RULES_PATH = process.env.CATEGORY_RULES_PATH || 'scripts/category-rules.json';

export function loadRules(path = RULES_PATH) {
  if (!existsSync(path)) throw new Error('category rules not found at ' + path + ' (commit scripts/category-rules.json first)');
  const r = JSON.parse(readFileSync(path, 'utf8'));
  if (!(r && r.sufficiency && r.categories)) throw new Error('category rules at ' + path + ' are not in the expected shape');
  return r;
}

const baseDomain = host => String(host || '').toLowerCase().split('.').slice(-2).join('.');

// Short lowercased excerpts where a pattern matches within `window` characters of the subject's name.
// One excerpt per pattern, at most `max` in all. A bad pattern in the rules file is skipped, not fatal.
export function evidence(text, patterns, lead, window = 300, max = 3) {
  const found = [];
  if (!text || !lead) return found;
  const leadRe = new RegExp('\\b' + lead + '\\b');
  for (const p of patterns || []) {
    let re;
    try { re = new RegExp(p, 'gi'); } catch (_e) { continue; }
    let m, guard = 0;
    while ((m = re.exec(text)) && guard++ < 300) {
      if (m[0] === '') { re.lastIndex++; continue; }
      const a = Math.max(0, m.index - window), b = Math.min(text.length, m.index + m[0].length + window);
      if (leadRe.test(text.slice(a, b))) {
        found.push(text.slice(Math.max(0, m.index - 70), Math.min(text.length, m.index + m[0].length + 70)).trim());
        break;
      }
    }
    if (found.length >= max) break;
  }
  return found;
}

// subject: { name, category, year }.  found: the result of findSources().  opts: { mode: 'new'|'rewrite' }.
export function assess(subject, found, rules, opts = {}) {
  const mode = opts.mode === 'rewrite' ? 'rewrite' : 'new';
  const suff = rules.sufficiency;
  const window = rules.window || 300;
  const toks = fold(subject.name).tokens;
  const generic = new Set((rules.genericNameWords || []).map(w => plainWords(w)));
  const specific = toks.filter(t => !generic.has(t));
  const lead = (specific.length ? specific : toks).slice().sort((a, b) => b.length - a.length)[0];
  const usable = (found.sources || []).filter(s => s.usable);
  const verify = usable.filter(s => s.status === 'approved' && s.canVerify);
  const reported = usable.filter(s => s.status === 'approved' && !s.canVerify);
  const unjudged = usable.filter(s => s.status === 'unjudged');
  const sum = list => list.reduce((n, s) => n + (s.words || 0), 0);
  const minM = suff.minMentionsPerPage || 0;
  const selection = selectSources(found.sources, rules, subject.category);
  // The enough-to-write-from check runs on the SELECTED pages only: what the writer will actually be given.
  const substantive = selection.picked.filter(s => s.canVerify && (s.mentions || 0) >= minM);   // really about the subject, not a passing mention
  const verifyWords = sum(substantive);
  const domains = new Set(substantive.map(s => baseDomain(s.domain)));
  const minDomains = mode === 'new' ? Math.max(1, suff.newSubjectMinDomains || 1) : 1;
  const enough = verifyWords >= suff.minWordsVerifyCapable && domains.size >= minDomains;
  const rich = suff.targetWordsVerifyCapable != null ? (verifyWords >= suff.targetWordsVerifyCapable && domains.size >= minDomains) : enough;
  const sufficiency = { verifyCapableWords: verifyWords, minWords: suff.minWordsVerifyCapable, targetWords: suff.targetWordsVerifyCapable,
    substantivePages: substantive.length, independentVerifyDomains: domains.size, minDomains, enough, rich,
    reportedPages: reported.length, unjudgedPages: unjudged.length };
  const flags = [];
  const decisions = [];
  const out = { mode, sufficiency, flags, decisions };

  if (!usable.length) { out.status = 'not_found'; out.reason = 'no page was fetched that names the subject'; return out; }
  out.selection = { selected: selection.selected, alsoFound: selection.alsoFound };
  if (selection.selected.length < (((rules.selection || {}).targetSelected) || 3)) flags.push('few_sources');

  // Perspective coverage (reported, never blocking): which kinds of site did we manage to hear from?
  const plan = perspectivePlan(rules, subject.category);
  if (plan) {
    const cov = laneCoverage(found.sources || [], plan);
    const covered = plan.lanes.filter(l => cov[l.id].covered).map(l => ({ id: l.id, label: l.label, words: cov[l.id].words, pages: cov[l.id].pages, ...(l.contextOnly ? { contextOnly: true } : {}) }));
    const missing = plan.lanes.filter(l => !cov[l.id].covered).map(l => l.id);
    out.perspectives = { wanted: plan.lanes.map(l => l.id), covered, missing };
    if (covered.length < Math.min(plan.minLanesForRich, plan.lanes.length)) flags.push('narrow_perspective');
  }

  // 1. Enough to write from? (Thin material no longer stops the checks: the category result is worked out too and reported beside it,
  //    so a Blessed with thin sources shows BOTH "too thin" and "not canonized".)
  let thin = false;
  if (!enough) {
    thin = true;
    const withUnjudged = verifyWords + sum(unjudged);   // unjudged pages are assumed substantive until Ignatius looks
    if (unjudged.length && withUnjudged >= suff.minWordsVerifyCapable) {
      out.status = 'needs_decision';
      decisions.push({ kind: 'unjudged_sources', urls: unjudged.map(s => s.url),
        reason: 'approved sources alone are too thin (' + verifyWords + ' of ' + suff.minWordsVerifyCapable + ' words), but these unjudged pages might make it enough; Ignatius and Tom decide whether they can be used' });
      out.reason = decisions[0].reason;
    } else {
      out.status = 'too_thin';
      out.reason = verify.length
        ? 'only ' + verifyWords + ' words of real material (need ' + suff.minWordsVerifyCapable + ') on ' + domains.size + ' verify-capable site(s)' + (domains.size < minDomains ? '; need ' + minDomains + ' independent sites' : '')
        : 'nothing found that can verify: ' + (reported.length ? reported.length + ' reported-tier page(s) cannot carry verification' : unjudged.length + ' unjudged page(s) are not yet approved');
    }
  } else {
    if (domains.size === 1) flags.push('single_source');
    if (!rich) flags.push('thin_material');
  }

  // 2. Category rules. Evidence comes from verify-capable pages only.
  const reasons = [];            // { kind, text }
  const ev = {};
  let basis = null;
  const cat = rules.categories[subject.category];
  const joined = verify.map(v => v.text || '').join(' ');
  const find = pats => evidence(joined, pats, lead, window);

  const nameWords = ' ' + plainWords(subject.name) + ' ';
  const scandalHit = ((rules.scandal && rules.scandal.nameTerms) || []).find(t => nameWords.includes(' ' + plainWords(t) + ' '));
  if (scandalHit) reasons.push({ kind: 'scandal', text: 'the name suggests a scandal ("' + scandalHit + '"); scandals go to review' });

  if (!cat) {
    reasons.push({ kind: 'category', text: 'category "' + subject.category + '" is not in the rules file' });
  } else if (cat.kind === 'saint') {
    const yr = subject.year;
    const partial = [];            // veneration signals that were found but did not add up to a basis
    const qualified = [];          // every basis that qualified, in priority order (the first becomes verdict.basis)
    for (const [name, b] of Object.entries(cat.bases || {})) {
      if (b.maxYear != null && !(yr != null && yr <= b.maxYear)) continue;
      if (b.signals) {
        // Different KINDS of evidence, not one phrase (see category-rules.json, ancient_veneration).
        const sig = {};
        for (const [type, def] of Object.entries(b.signals)) {
          const h = find(def.patterns);
          if (h.length) sig[type] = { strength: def.strength, excerpts: h };
        }
        // SITE signals: evidence that is where a page lives (an Orthodox site's own entry for him), not what it says.
        for (const v of verify) {
          let u;
          try { u = new URL(v.url); } catch (_e) { continue; }
          const host = u.hostname.toLowerCase(), path = u.pathname.toLowerCase();
          for (const sd of b.siteSignals || []) {
            if (!(host === sd.domain || host.endsWith('.' + sd.domain))) continue;
            if (sd.pathPrefix && !path.startsWith(sd.pathPrefix)) continue;
            if (sd.nameInSlug && !(lead && path.includes(lead))) continue;
            if ((v.mentions || 0) < (sd.minMentions || 1)) continue;
            const def = b.signals[sd.signal];
            if (!def) continue;
            const slot = sig[sd.signal] || (sig[sd.signal] = { strength: def.strength, excerpts: [] });
            if (slot.excerpts.length < 4) slot.excerpts.push('[site] ' + sd.label + ': ' + v.url);
          }
        }
        const types = Object.keys(sig);
        if (!types.length) continue;
        const cautions = find(b.cautions);
        const rule = b.accept || {};
        const strong = types.filter(t => sig[t].strength === 'strong');
        const decisive = (rule.decisiveTypes || []).some(t => sig[t]);
        const meets = decisive || (types.length >= (rule.minDistinctTypes == null ? 2 : rule.minDistinctTypes) && strong.length >= (rule.minStrong == null ? 1 : rule.minStrong));
        ev[name] = { signals: sig, ...(cautions.length ? { cautions } : {}) };
        if (meets && !cautions.length) { qualified.push(name); if (!basis) basis = name; }
        else if (cautions.length) partial.push('veneration signals found (' + types.join(', ') + ') but the sources raise doubt about the person; a human must decide');
        else partial.push(strong.length ? 'only one kind of veneration signal (' + types.join(', ') + '); ' + (rule.minDistinctTypes || 2) + ' different kinds are needed'
          : 'no strong veneration signal (only ' + types.join(', ') + '); at least one strong kind is needed');
        continue;
      }
      const hits = find(b.patterns);
      if (hits.length) { ev[name] = hits; qualified.push(name); if (!basis) basis = name; }
    }
    if (qualified.length > 1) ev.also_qualified = qualified.slice(1);
    if (!basis) {
      const nc = {};
      for (const [name, pats] of Object.entries(cat.notCanonized || {})) { if (name.startsWith('_')) continue; const h = find(pats); if (h.length) nc[name] = h; }
      if (Object.keys(nc).length) { ev.not_canonized = nc; reasons.push({ kind: 'basis', text: 'not canonized: the sources suggest ' + Object.keys(nc).join(' / ').replace(/_/g, ' ') + ' status, and no basis for sainthood was found' }); }
      else if (partial.length) reasons.push({ kind: 'basis', text: partial.join('; ') + '; no other basis for sainthood found' });
    else reasons.push({ kind: 'basis', text: 'no basis for sainthood found near the name (New Testament figure, ancient veneration, or formal canonization)' });
    }
  } else if (cat.kind === 'review') {
    let sig = cat.signals;
    if (typeof sig === 'string') sig = (rules.categories[sig.replace(/^same as /, '')] || {}).signals;
    const sigs = {};
    for (const [name, pats] of Object.entries(sig || {})) { const h = find(pats); if (h.length) sigs[name] = h; }
    if (Object.keys(sigs).length) ev.approval_signals = sigs;
    // Approval news usually appears in REPORTED sources (National Catholic Register, OSV...), which cannot verify. Show what they say as leads
    // to check against the bishop's or the Dicastery's own statement; this is never proof and never changes the verdict.
    const repText = reported.map(v => v.text || '').join(' ');
    const repSigs = {};
    for (const [name, pats] of Object.entries(sig || {})) { const h = evidence(repText, pats, lead, window); if (h.length) repSigs[name] = h; }
    if (Object.keys(repSigs).length) ev.approval_signals_reported = repSigs;
    reasons.push({ kind: 'basis', text: cat.reason || 'this category is set to review' });
  } else if (cat.kind === 'reject') {
    reasons.push({ kind: 'reject', text: cat.reason || 'this category is not accepted' });
  }
  // kind "accept": nothing further to check

  // In rewrite mode the basis checks are advisory (the entry already exists); a scandal still blocks.
  const blocking = reasons.filter(r => r.kind === 'scandal' || r.kind === 'reject' || mode === 'new' || rules.enforceBasisChecksInRewrite === true);
  const advisory = reasons.filter(r => !blocking.includes(r));
  out.verdict = { action: blocking.some(r => r.kind === 'reject') ? 'reject' : blocking.length ? 'review' : 'accept',
    basis, reasons: blocking, ...(advisory.length ? { advisory } : {}), evidence: ev };
  if (advisory.length) flags.push('category_advisory');

  if (thin) {
    // keep the sufficiency status; add the category result beside it
    if (out.verdict.action !== 'accept') {
      decisions.push({ kind: 'category_' + out.verdict.action, reason: blocking.map(r => r.text).join('; ') });
      out.reason = (out.reason ? out.reason + '. ALSO: ' : '') + decisions[decisions.length - 1].reason;
    }
  } else if (out.verdict.action === 'accept') { out.status = 'ready'; }
  else {
    out.status = 'needs_decision';
    decisions.push({ kind: 'category_' + out.verdict.action, reason: blocking.map(r => r.text).join('; ') });
    out.reason = decisions[decisions.length - 1].reason;
  }
  return out;
}

// ---------------------------------------------------------------------------------------------
// Orchestrator handler (not registered yet). Layer 2 writes no files; layer 1 uses no model.
// payload: { mode, name, category, year, entityId, confirmNew, search, allowlistOnly, model }
//   confirmNew: after a possible_match, a human says "different subject"; proceed to search.
//   search:     false = layer 1 only.
//   assess:     false = skip layer 3 (default: layer 3 runs after a search).
// ---------------------------------------------------------------------------------------------

export async function runSourceFinder(task, dataJson, deps = {}) {
  const p = task.payload || {};
  tokensUsed = 0;
  usageTally = newTally();
  authoritySearches = 0;
  const out = findSubject({ mode: p.mode, name: p.name, category: p.category, year: p.year, entityId: p.entityId || task.entityId }, dataJson);

  const proceed = p.search !== false && (out.outcome === 'new_subject' || out.outcome === 'rewrite_ready' ||
    (out.outcome === 'possible_match' && p.confirmNew === true));
  let found = null;
  if (proceed) {
    const subject = out.outcome === 'rewrite_ready'
      ? { name: out.subject.name, category: out.subject.category, year: out.subject.year,
          links: ((((dataJson.entries || []).find(e => e.id === out.subject.id) || {}).art || {}).links || []) }
      : out.subject;
    const tStart = Date.now();
    let rules = null, rulesError = null;
    try { rules = deps.rules || loadRules(); } catch (err) { rulesError = String((err && err.message) || err).slice(0, 300); }
    const mode = out.outcome === 'rewrite_ready' ? 'rewrite' : 'new';
    const opts = { allowlistOnly: p.allowlistOnly === true, model: p.model };
    if (rules) { opts.minWords = rules.sufficiency.minWordsVerifyCapable; opts.targetWords = rules.sufficiency.targetWordsVerifyCapable; opts.minMentions = rules.sufficiency.minMentionsPerPage || 0; opts.minDomains = mode === 'new' ? Math.max(1, rules.sufficiency.newSubjectMinDomains || 1) : 1; opts.perspectives = perspectivePlan(rules, subject.category); opts.poolTarget = (rules.selection && rules.selection.poolTarget) || 0; opts.blockedDomains = rules.fetchBlockedDomains || []; }
    try {
      found = await findSources(subject, opts, deps);
    } catch (err) {
      if (err && err.deferred) throw err;
      out.search = { error: String((err && err.message) || err).slice(0, 300) };
    }
    if (found) {
      out.search = found;
      out.layer2 = found.counts.usableApproved + found.counts.usableUnjudged > 0 ? 'candidates_found' : 'no_candidates';
      if (p.assess !== false) {
        try { if (!rules) throw new Error(rulesError); out.layer3 = assess(subject, found, rules, { mode }); }
        catch (err) { out.layer3 = { status: 'error', reason: String((err && err.message) || err).slice(0, 300) }; }
      }
      // Which diocese judges this, and what is its own website? Only for categories the rules list (apparitions, miracles); never fails the run.
      const al = rules && rules.authorityLookup;
      if (p.authority !== false && al && al.enabled !== false && (al.categories || []).includes(subject.category)) {
        try {
          out.authority = await findAuthority({
            subject: { name: subject.name, year: subject.year, region: out.subject && out.subject.region }, label: CATEGORY_LABEL[subject.category] || 'subject',
            ask: deps.askAuthority || (a => realAsk({ ...a, model: p.model })), fetchPage: deps.fetchPage || realFetchPage,
            reg: deps.registry || loadRegistry(), helpers: { safeUrl, regEntry, neverHosts: NEVER_HOSTS }, cfg: al });
          authoritySearches = out.authority.searches || 0;
        } catch (err) {
          if (err && err.deferred) throw err;
          out.authority = { found: false, error: String((err && err.message) || err).slice(0, 200) };
        }
      }
      out.timing = { seconds: Math.round((Date.now() - tStart) / 100) / 10, webSearches: (found.webSearches || 0) + authoritySearches, searchCalls: (found.searchCalls || 0) + (authoritySearches ? 1 : 0),
        pagesFetched: (found.passes || []).reduce((n, x) => n + (x.fetched || 0), 0),
        model: p.model || FINDER_MODEL.modelId, inputTokens: usageTally.input, outputTokens: usageTally.output,
        cacheReadTokens: usageTally.cacheRead, cacheWriteTokens: usageTally.cacheWrite,
        ...(usageTally.long.input || usageTally.long.output || usageTally.long.cacheRead || usageTally.long.cacheWrite
          ? { longPrompt: { inputTokens: usageTally.long.input, outputTokens: usageTally.long.output, cacheReadTokens: usageTally.long.cacheRead, cacheWriteTokens: usageTally.long.cacheWrite } } : {}) };
    }
  }

  const cnt = found ? found.counts : null;
  let summary;
  switch (out.outcome) {
    case 'exists': summary = out.subject.name + ' is already on the timeline as ' + out.match.name + ' (' + out.match.id + ', ' + out.level + ' match)'; break;
    case 'possible_match': summary = out.subject.name + ': similar entries exist (' + out.matches.map(m => m.name + ' ' + m.score).join(', ') + ')' +
      (found ? ' — proceeded because confirmNew was set' : ' — needs a human look; re-queue with confirmNew:true if it is a different subject'); break;
    case 'new_subject': summary = out.subject.name + ' is not on the timeline'; break;
    case 'rewrite_ready': summary = 'rewrite of ' + out.subject.name + ' (' + out.subject.id + ')'; break;
    default: summary = 'error — ' + out.reason;
  }
  if (cnt) summary += ' | sources: ' + cnt.usableApproved + ' usable allowlisted, ' + cnt.usableUnjudged + ' usable unjudged, ' +
    cnt.unusable + ' unusable, ' + cnt.totalWordsUsable + ' words' + (found.widened ? ' (widened to open web)' : '') +
    (out.layer3 ? ' | layer 3: ' + out.layer3.status + (out.layer3.reason ? ' — ' + out.layer3.reason : '') + (out.layer3.flags && out.layer3.flags.length ? ' [' + out.layer3.flags.join(', ') + ']' : '') : '') +
    (out.layer3 && out.layer3.selection ? ' | selected ' + out.layer3.selection.selected.length + ' of ' + (out.layer3.selection.selected.length + out.layer3.selection.alsoFound.length) + ' pages' : '') +
    (out.layer3 && out.layer3.perspectives ? ' | perspectives ' + out.layer3.perspectives.covered.length + '/' + out.layer3.perspectives.wanted.length +
      ' (' + out.layer3.perspectives.covered.map(c => c.id).join(', ') + (out.layer3.perspectives.missing.length ? '; missing ' + out.layer3.perspectives.missing.join(', ') : '') + ')' : '');
  else if (out.search && out.search.error) summary += ' | source search failed: ' + out.search.error;
  return { result: out, summary: summary.slice(0, 900), provider: found ? FINDER_MODEL.provider : 'none', tokensUsed };
}

// ---------------------------------------------------------------------------------------------
// Orchestrator entry point (task type 'source-find').  The orchestrator calls handler(task, dataJson, workLog).
//   task.payload: the same fields as runSourceFinder, plus  jobId (links this run to the article job's log; defaults to the
//   task id) and requestedBy (optional name shown in the log).
// Adds Jerome's steps to article-log.json and returns filesToCommit: [that file] so the orchestrator commits it.
// A failure to write the log never fails the task: it is reported in the summary instead.
// ---------------------------------------------------------------------------------------------

// Put the NEW diocese sites found in this run into ignatius-queue.json as "waiting". Returns { added, merged, skipped, changed }.
export function recordHandoff({ result, task, jobId, queuePath = QUEUE_PATH, now = new Date() }) {
  const a = result && result.authority;
  const none = { added: 0, merged: 0, skipped: 0, changed: false };
  if (!a || !a.candidates) return none;
  const p = (task && task.payload) || {};
  const items = queueItemsFor(a, { subject: { name: (result.subject && result.subject.name) || p.name || 'Untitled' }, jobId: jobId || p.jobId || (task && task.id) || null, at: now.toISOString() });
  if (!items.length) return none;
  const q = loadQueue(queuePath);
  const r = addToQueue(q, items);
  const changed = r.added > 0 || r.merged > 0;
  if (changed) saveQueue(q, queuePath);
  return { added: r.added, merged: r.merged, skipped: r.skipped, changed };
}

// Save the sources file for this run (see sources-file.mjs). Returns { path } or { skipped: reason }. Never throws.
export function recordSources({ result, task, jobId, dir = SOURCES_DIR, registry, now = new Date() }) {
  try {
    if (!result || !result.layer3 || !result.layer3.selection) return { skipped: 'no search was run' };
    let reg = registry;
    if (!reg) { try { reg = loadRegistry(); } catch (_e) { reg = null; } }
    const storageOf = d => { const e = reg ? regEntry(reg, d) : null; return e && e.storage === 'full' ? 'full' : 'excerpts'; };
    const file = buildSourcesFile(result, { task, jobId, now, finder: 'source-finder v0.9.7', storageOf });
    return { path: writeSourcesFile(file, dir), entryId: file.entryId, outcome: file.outcome, stored: file.sources.filter(x => x.storage === 'full').length };
  } catch (err) {
    return { skipped: String((err && err.message) || err).slice(0, 140) };
  }
}

// What is kept on the task in workLog.json: everything a person or the next step needs, minus the long per-page records.
export function compactResult(r) {
  const c = { ...r };
  if (c.search && c.search.sources) c.search = { widened: c.search.widened, passes: c.search.passes, counts: c.search.counts, webSearches: c.search.webSearches, searchCalls: c.search.searchCalls };
  return c;
}

export async function runJerome(task, dataJson, _workLog, deps = {}) {
  const out = await runSourceFinder(task, dataJson, deps);
  const logPath = deps.logPath || LOG_PATH;
  let note = '';
  const filesToCommit = [];
  try {
    const job = recordJerome({ result: out.result, task, logPath, now: deps.now });
    filesToCommit.push(logPath);
    const h = recordHandoff({ result: out.result, task, jobId: job.id, queuePath: deps.queuePath || QUEUE_PATH, now: deps.now });
    if (h.changed) { filesToCommit.push(deps.queuePath || QUEUE_PATH); note = ' | handed ' + (h.added + h.merged) + ' site(s) to Ignatius'; }
    const sf = recordSources({ result: out.result, task, jobId: job.id, dir: deps.sourcesDir || SOURCES_DIR, registry: deps.registry, now: deps.now });
    if (sf.path) { filesToCommit.push(sf.path); note += ' | saved ' + sf.path; }
  } catch (err) {
    note = ' | article log not written: ' + String((err && err.message) || err).slice(0, 120);
  }
  return { ...out, result: compactResult(out.result), summary: (out.summary + note).slice(0, 900), ...(filesToCommit.length ? { filesToCommit } : {}) };
}

// ---------------------------------------------------------------------------------------------
// CLI:  node scripts/services/source-finder.mjs "St. Bertha" --category s [--year 723] [--search] [--confirm-new] [--log] [--job <id>] [--model <model id>]
//       node scripts/services/source-finder.mjs --rewrite st-augustine-430 [--search]
// Without --search only layer 1 runs (no network). --search needs ANTHROPIC_API_KEY.
// ---------------------------------------------------------------------------------------------

async function cli(argv) {
  const args = argv.slice(2);
  const get = flag => { const i = args.indexOf(flag); return i >= 0 ? args[i + 1] : undefined; };
  const rewrite = get('--rewrite');
  const name = args.find((a, i) => !a.startsWith('--') && !['--category', '--year', '--rewrite', '--job', '--model'].includes(args[i - 1]));
  const dataJson = JSON.parse(readFileSync(DATA_PATH, 'utf8'));
  const task = { payload: rewrite
    ? { mode: 'rewrite', entityId: rewrite, search: args.includes('--search'), model: get('--model') }
    : { mode: 'new', name, category: get('--category'), year: get('--year'), search: args.includes('--search'),
        confirmNew: args.includes('--confirm-new'), model: get('--model') } };
  const out = await runSourceFinder(task, dataJson);
  console.log(out.summary);
  console.log(JSON.stringify(out.result, null, 2));
  if (args.includes('--log')) {                                // add this run to article-log.json (the pilot workflow commits it)
    const job = recordJerome({ result: out.result, task: { payload: { ...task.payload, jobId: get('--job') } } });
    console.error('\n' + renderJob(job, loadPricing()).join('\n'));
    const h = recordHandoff({ result: out.result, task, jobId: job.id });
    if (h.changed) console.error('\nHanded to Ignatius: ' + (h.added + h.merged) + ' site(s) now waiting in ' + QUEUE_PATH);
    const sf = recordSources({ result: out.result, task, jobId: job.id });
    if (sf.path) console.error('\nSaved ' + sf.path + ' (' + sf.outcome + (sf.stored ? '; full text stored for ' + sf.stored + ' public-domain source(s)' : '; no full text stored') + ')');
    else console.error('\nSources file not saved: ' + sf.skipped);
  }
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) cli(process.argv).catch(e => { console.error(e.message || e); process.exit(1); });

// scripts/services/article-log.mjs
// MODULE DATE: 2026-10-09 (Friday) · v0.8 — the article log: a short, readable record of what happened on each article job.
//
// WHAT IT KEEPS (article-log.json, repo root, committed like workLog.json):
//   { "version": 1, "jobs": [ { "id", "title", "kind": "rewrite" | "new", "startedAt", "requestedBy", "status", "totalSeconds",
//        "steps": [ { "n", "who", "text", "at", "seconds",
//                     "usage": { "model", "inputTokens", "outputTokens", "cacheReadTokens", "cacheWriteTokens", "webSearches",
//                                "longPrompt": { same four token fields, for requests over the long-prompt threshold }, "otherUsd" } } ] } ] }
//   inputTokens is the NEW (uncached) input, as the API reports it; cache reads and writes are separate and priced separately.
//   Each service adds its own steps to the SAME job by passing the same jobId (task.payload.jobId, else the task id).
//   Steps are written by CODE from real numbers (pages, words, seconds, tokens), never by an AI, so the numbers can be trusted.
//   The log is kept apart from workLog.json so the work log's pruning never touches it. It keeps the newest MAX_JOBS jobs,
//   and drops jobs older than MAX_AGE_DAYS (Claude's guess for "a while"; change the two constants or the env vars).
//
// COST (scripts/pricing.json, editable): the log stores RAW usage per step (tokens by model, web searches). Dollars are worked
//   out when the log is shown, from the pricing file, so a price change corrects every old job. A step with no usage shows no
//   cost. A price marked "verified": false is an assumption and the cost shows an asterisk until Tom confirms it.
//   Tom's rule: "the models dictate how expensive each thing is": so the model name is stored on every step that spent tokens.
//
// NOT BUILT YET: the Log view in the website (index.html), steps for the writer / verifier / reworder / recorder services
//   (they will call addStep with the same jobId), human events such as "Tom approved a new site" (needs the approval feature).

import { readFileSync, writeFileSync, existsSync, mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

export const LOG_PATH = process.env.ARTICLE_LOG_PATH || 'article-log.json';
export const PRICING_PATH = process.env.PRICING_PATH || 'scripts/pricing.json';
export const MAX_JOBS = parseInt(process.env.ARTICLE_LOG_MAX_JOBS || '200', 10);
export const MAX_AGE_DAYS = parseInt(process.env.ARTICLE_LOG_MAX_AGE_DAYS || '90', 10);

export function loadLog(path = LOG_PATH) {
  try {
    const l = JSON.parse(readFileSync(path, 'utf8'));
    if (l && Array.isArray(l.jobs)) return l;
  } catch (_e) { /* missing or unreadable: start fresh */ }
  return { version: 1, jobs: [] };
}

export function saveLog(log, path = LOG_PATH) {
  mkdirSync(dirname(path) || '.', { recursive: true });
  writeFileSync(path, JSON.stringify(log, null, 1) + '\n');
}

export function loadPricing(path = PRICING_PATH) {
  try { return JSON.parse(readFileSync(path, 'utf8')); } catch (_e) { return null; }
}

const slug = s => String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 40) || 'job';
export const jobIdFor = (title, atIso) => 'job-' + String(atIso).slice(0, 16).replace(/[-:T]/g, '') + '-' + slug(title);   // to the minute, so two runs the same day are two jobs

// Find the job with this id, or open it.
export function openJob(log, { id, title, kind, requestedBy, at }) {
  let job = log.jobs.find(j => j.id === id);
  if (!job) {
    job = { id, title: title || id, kind: kind || 'new', startedAt: at, requestedBy: requestedBy || null, status: 'open', totalSeconds: 0, steps: [] };
    log.jobs.push(job);
  }
  return job;
}

// Add one step. Returns the step. Numbers only from real measurements; seconds may be null (instant or unknown).
export function addStep(job, { who, text, at, seconds = null, usage = null }) {
  const step = { n: job.steps.length + 1, who, text: String(text).slice(0, 400), at, seconds: seconds == null ? null : Math.round(seconds * 10) / 10 };
  if (usage) {
    const u = {};
    if (usage.model) u.model = usage.model;
    for (const k of ['inputTokens', 'outputTokens', 'cacheReadTokens', 'cacheWriteTokens', 'webSearches', 'otherUsd']) if (usage[k]) u[k] = usage[k];
    if (usage.longPrompt) {
      const lp = {};
      for (const k of ['inputTokens', 'outputTokens', 'cacheReadTokens', 'cacheWriteTokens']) if (usage.longPrompt[k]) lp[k] = usage.longPrompt[k];
      if (Object.keys(lp).length) u.longPrompt = lp;
    }
    if (Object.keys(u).length) step.usage = u;
  }
  job.steps.push(step);
  job.totalSeconds = Math.round(job.steps.reduce((n, s) => n + (s.seconds || 0), 0) * 10) / 10;
  return step;
}

export function finishJob(job, status = 'done') { job.status = status; return job; }

// Keep the newest MAX_JOBS jobs and nothing older than MAX_AGE_DAYS. Returns how many were dropped.
export function prune(log, { maxJobs = MAX_JOBS, maxAgeDays = MAX_AGE_DAYS, now = new Date() } = {}) {
  const cutoff = now.getTime() - maxAgeDays * 86400000;
  const before = log.jobs.length;
  log.jobs = log.jobs.filter(j => Date.parse(j.startedAt) >= cutoff || !Number.isFinite(Date.parse(j.startedAt)));
  log.jobs.sort((a, b) => String(a.startedAt).localeCompare(String(b.startedAt)));
  if (log.jobs.length > maxJobs) log.jobs = log.jobs.slice(log.jobs.length - maxJobs);
  return before - log.jobs.length;
}

// ---- cost ----
// Returns { usd, assumed, missing }: usd is null when nothing could be priced. assumed = used a price marked unverified.
// missing = the step spent something the pricing file has no price for (never guessed).
// Tokens are priced in buckets: the normal bucket, and (for a model with a longPrompt price, such as Haiku 5.5) a second bucket for
// requests whose prompt was over the threshold. Within a bucket: new input, cache writes (5-minute), cache reads, output.
function bucketCost(b, rates) {
  let usd = 0, missing = false;
  const parts = [['inputTokens', 'inputPerMTok'], ['outputTokens', 'outputPerMTok'], ['cacheReadTokens', 'cacheReadPerMTok'], ['cacheWriteTokens', 'cacheWritePerMTok']];
  for (const [tok, rate] of parts) {
    if (!b[tok]) continue;
    if (rates[rate] == null) missing = true;
    else usd += b[tok] * rates[rate] / 1e6;
  }
  return { usd, missing };
}
const hasTokens = b => !!(b && (b.inputTokens || b.outputTokens || b.cacheReadTokens || b.cacheWriteTokens));

export function costOfStep(step, pricing) {
  const u = step && step.usage;
  if (!u || !pricing) return { usd: null, assumed: false, missing: !!u };
  let usd = 0, priced = false, assumed = false, missing = false;
  if (u.webSearches) {
    if (pricing.webSearchPer1000 != null) { usd += u.webSearches * pricing.webSearchPer1000 / 1000; priced = true; if (pricing.webSearchVerified === false) assumed = true; }
    else missing = true;
  }
  if (hasTokens(u) || hasTokens(u.longPrompt)) {
    const m = pricing.models && pricing.models[u.model];
    if (!m) missing = true;
    else {
      for (const [bucket, rates] of [[u, m], [u.longPrompt, m.longPrompt ? { ...m, ...m.longPrompt } : m]]) {
        if (!hasTokens(bucket)) continue;
        const c = bucketCost(bucket, rates);
        if (c.missing) missing = true; else { usd += c.usd; priced = true; }
      }
      if (m.verified === false) assumed = true;
    }
  }
  if (u.otherUsd) { usd += u.otherUsd; priced = true; }
  return { usd: priced ? Math.round(usd * 1e6) / 1e6 : null, assumed, missing };
}

export function costOfJob(job, pricing) {
  let usd = 0, any = false, assumed = false, missing = false;
  for (const s of job.steps || []) {
    const c = costOfStep(s, pricing);
    if (c.usd != null) { usd += c.usd; any = true; }
    if (c.assumed) assumed = true;
    if (c.missing) missing = true;
  }
  return { usd: any ? Math.round(usd * 1e6) / 1e6 : null, assumed, missing };
}

// ---- display ----
const mins = sec => sec == null ? null : (Math.round(sec / 6) / 10) + ' min';           // 174 s -> "2.9 min"
const money = c => c.usd == null ? null : '$' + (c.usd < 0.01 ? c.usd.toFixed(4) : c.usd.toFixed(2)) + (c.assumed ? '*' : '');
const k = n => n >= 1000 ? (Math.round(n / 100) / 10) + 'k' : String(n);

export function stepDetail(step, pricing) {
  const bits = [];
  const t = mins(step.seconds);
  if (t) bits.push(t);
  const u = step.usage;
  if (u) {
    const lp = u.longPrompt || {};
    const inT = (u.inputTokens || 0) + (lp.inputTokens || 0), outT = (u.outputTokens || 0) + (lp.outputTokens || 0);
    const cached = (u.cacheReadTokens || 0) + (lp.cacheReadTokens || 0);
    if (inT || outT || cached) bits.push(k(inT) + ' in' + (cached ? ' + ' + k(cached) + ' cached' : '') + ' / ' + k(outT) + ' out tokens' + (u.model ? ' (' + u.model + ')' : ''));
    if (u.webSearches) bits.push(u.webSearches + ' web search' + (u.webSearches === 1 ? '' : 'es'));
    const c = costOfStep(step, pricing);
    const m = money(c);
    if (m) bits.push(m);
    else if (c.missing) bits.push('cost unknown: no price set');
  }
  return bits.join(', ');
}

// Plain-text lines for one job, in the shape Tom asked for.
export function renderJob(job, pricing = null) {
  const lines = [];
  const when = String(job.startedAt || '').replace('T', ' ').slice(0, 16);
  lines.push((job.title || job.id) + (job.kind ? ' (' + job.kind + ')' : '') + ' — ' + when + ' UTC');
  for (const s of job.steps || []) {
    const d = stepDetail(s, pricing);
    lines.push(s.n + '. ' + s.who + ': ' + s.text + (d ? ' (' + d + ')' : ''));
  }
  const c = costOfJob(job, pricing);
  const total = ['Total working time ' + (mins(job.totalSeconds) || '0 min')];   // the steps' own time; GitHub's run time adds about a minute of setup
  const m = money(c);
  if (m) total.push('cost ' + m);
  lines.push(total.join(' · '));
  if (m && c.assumed) lines.push('* includes a price that is not confirmed yet (scripts/pricing.json)');
  return lines;
}

// ---- Jerome's steps ----
const siteName = d => String(d || '').replace(/^www\./, '');
const baseDom = h => String(h || '').toLowerCase().split('.').slice(-2).join('.');

const dropUndefined = o => Object.fromEntries(Object.entries(o).filter(([, v]) => v !== undefined));

// Steps from a (raw) source-finder result. result.timing is added by runSourceFinder when a search ran.
export function jeromeSteps(result, { at } = {}) {
  const steps = [];
  const s = result.subject || {};
  const name = s.name || 'the subject';
  const what = result.mode === 'rewrite' ? 'rewrite of ' + name : 'new article: ' + name;
  steps.push({ who: 'Jerome', text: 'Got request for ' + what, at });
  if (result.outcome === 'error') { steps.push({ who: 'Jerome', text: 'Could not handle the request: ' + result.reason, at }); return steps; }
  if (result.outcome === 'exists') { steps.push({ who: 'Jerome', text: 'Already on the timeline as ' + (result.match && result.match.name) + '; nothing to do', at }); return steps; }
  if (result.outcome === 'possible_match' && !result.search) {
    steps.push({ who: 'Jerome', text: 'Similar entries exist (' + (result.matches || []).map(m => m.name).join(', ') + '); waiting for a person to decide', at });
    return steps;
  }
  const L3 = result.layer3;
  if (result.search && result.search.counts) {
    const c = result.search.counts;
    const usable = (result.search.sources || []).filter(x => x.usable);
    const hosts = usable.length ? usable.map(x => x.domain)
      : L3 && L3.selection ? [...L3.selection.selected, ...L3.selection.alsoFound].map(x => x.domain) : [];
    const pages = c.usableApproved + c.usableUnjudged;
    const tm = result.timing || {};
    steps.push({ who: 'Jerome', at, seconds: tm.seconds,
      text: 'Found ' + pages + ' usable pages on ' + new Set(hosts.map(baseDom)).size + ' sites, ' + c.totalWordsUsable.toLocaleString('en-US') + ' words in all',
      usage: dropUndefined({ model: tm.model, inputTokens: tm.inputTokens, outputTokens: tm.outputTokens, cacheReadTokens: tm.cacheReadTokens,
               cacheWriteTokens: tm.cacheWriteTokens, longPrompt: tm.longPrompt, webSearches: tm.webSearches }) });
  } else if (result.search && result.search.error) {
    steps.push({ who: 'Jerome', text: 'Source search failed: ' + result.search.error, at });
    return steps;
  }
  if (L3 && L3.selection && L3.selection.selected.length) {
    const sel = L3.selection.selected;
    steps.push({ who: 'Jerome', at, text: 'Ranked the sites and kept the best ' + sel.length + ' of ' + (sel.length + L3.selection.alsoFound.length) + ': ' +
      sel.map((x, i) => (i + 1) + ' ' + siteName(x.domain) + (x.lane ? ' (' + x.lane.replace(/_/g, ' ') + ')' : '') + ' ' + x.score).join('; ') });
  }
  if (L3) {
    const bits = [L3.status === 'ready' ? 'Enough to write from' : L3.status === 'needs_decision' ? 'Needs a decision' : L3.status === 'too_thin' ? 'Too thin' : L3.status === 'not_found' ? 'Nothing found' : 'Check: ' + L3.status];
    if (L3.verdict && L3.verdict.basis) bits.push('basis: ' + L3.verdict.basis.replace(/_/g, ' ') + (L3.verdict.evidence && L3.verdict.evidence.also_qualified ? ' (also ' + L3.verdict.evidence.also_qualified.map(x => x.replace(/_/g, ' ')).join(', ') + ')' : ''));
    if (L3.verdict && L3.verdict.advisory && L3.verdict.advisory.length) bits.push('advice only (rewrite): ' + L3.verdict.advisory.map(x => x.text).join('; '));
    if (L3.reason) bits.push(L3.reason);
    if (L3.flags && L3.flags.length) bits.push('flags: ' + L3.flags.join(', '));
    steps.push({ who: 'Jerome', at, text: bits.join('; ') });
    // Unjudged sites that could make the material enough: a person (and later Ignatius) decides whether to approve them.
    const uj = (L3.decisions || []).find(d => d.kind === 'unjudged_sources');
    if (uj && uj.urls && uj.urls.length) {
      const count = {};
      for (const u of uj.urls) { try { const h = new URL(u).hostname.replace(/^www\./, ''); count[h] = (count[h] || 0) + 1; } catch (_e) { /* skip */ } }
      steps.push({ who: 'Jerome', at, text: 'Unjudged sites waiting for approval: ' + Object.entries(count).map(([h, n]) => h + (n > 1 ? ' (' + n + ' pages)' : '')).join(', ') });
    }
  }
  // The diocese lookup (apparitions and miracles): what was found and handed to Ignatius.
  const au = result.authority;
  if (au) {
    if (au.error) steps.push({ who: 'Jerome', at, text: 'Diocese lookup failed: ' + au.error });
    else if (!au.found) steps.push({ who: 'Jerome', at, text: 'Could not find the diocese\'s own website' + (au.note ? ' (' + au.note + ')' : '') });
    else {
      const where = [au.diocese, [au.place, au.country].filter(Boolean).join(', ')].filter(Boolean).join(' — ');
      for (const c of au.candidates) {
        const lead = (c.role === 'diocese' ? 'Diocese' : 'Other official') + ' website ' + (c.domain || c.url) + (c.role === 'diocese' && where ? ' (' + where + ')' : '');
        if (c.registry === 'new') {
          const ck = c.checks || {};
          steps.push({ who: 'Jerome', at, text: 'Handed to Ignatius: ' + lead + '; ' + (c.verified
            ? 'the page loads, names the diocese ' + ck.dioceseMentions + ' time(s) and reads like a church site'
            : 'NOT confirmed as a church site (' + (c.note || 'unknown') + ')') + '; waiting for his decision' });
        } else if (c.registry === 'approved') steps.push({ who: 'Jerome', at, text: lead + ' is already an approved source' });
        else if (c.registry === 'disabled') steps.push({ who: 'Jerome', at, text: lead + ' is on the registry but switched off' });
        else steps.push({ who: 'Jerome', at, text: lead + ' was skipped: ' + (c.note || 'not an allowed kind of site') });
      }
    }
  }
  return steps;
}

// Add Jerome's steps for one finished run to the log file. Returns the job.
export function recordJerome({ result, task, logPath = LOG_PATH, now = new Date() }) {
  const at = now.toISOString();
  const p = (task && task.payload) || {};
  const log = loadLog(logPath);
  const s = result.subject || {};
  const title = s.name || p.name || 'Untitled';
  const id = p.jobId || (task && task.id) || jobIdFor(title, at);
  const job = openJob(log, { id, title, kind: result.mode === 'rewrite' ? 'rewrite' : 'new', requestedBy: p.requestedBy, at });
  for (const st of jeromeSteps(result, { at })) addStep(job, st);
  prune(log, { now });
  saveLog(log, logPath);
  return job;
}

// ---- Thomas's steps (ledger-build: the source check of one article) ----
// ledger: the ledger object ledger-build writes (summary, sourceHealth, claims, pipeline?, usage?: [{ role, provider, model, calls, inputTokens, outputTokens,
// cacheReadTokens?, cacheWriteTokens? }], seconds?). The cost is NOT stored in the log: each step carries its role's tokens and model, and the dollars are worked out
// from scripts/pricing.json when a job is viewed, like Jerome's.
const usageOf = u => u ? dropUndefined({ model: u.model, inputTokens: u.inputTokens || undefined, outputTokens: u.outputTokens || undefined,
  cacheReadTokens: u.cacheReadTokens || undefined, cacheWriteTokens: u.cacheWriteTokens || undefined }) : null;

export function ledgerSteps(ledger, { at } = {}) {
  const s = ledger.summary || {};
  const claims = ledger.claims || [];
  const health = ledger.sourceHealth || [];
  const by = r => (ledger.usage || []).find(u => u.role === r);
  const steps = [];

  let read = 'Read ' + health.filter(h => h.ok).length + ' of ' + health.length + ' source page(s)';
  const pl = ledger.pipeline;
  if (pl) read += ' (Jerome\'s file: ' + pl.linked + ' linked in the article, ' + pl.notLinked + ' not linked, so only suggestions)';
  const drifted = health.filter(h => h.jerome && h.jerome.drift === 'changed').length;
  if (drifted) read += '; ' + drifted + ' page(s) differ in length from what Jerome saw';
  steps.push({ who: 'Thomas', at, text: read });

  const ex = by('extractor');
  steps.push({ who: 'Thomas', at, text: 'Listed ' + (s.total || 0) + ' claims to check' + (s.extractorRejected ? ' (' + s.extractorRejected + ' dropped: not copied word for word)' : ''), usage: usageOf(ex) });

  const withProof = claims.filter(c => c.sources && c.sources.length && c.status !== 'unsourced').length;
  const pv = by('prover');
  steps.push({ who: 'Thomas', at, text: 'Found a word-for-word excerpt for ' + withProof + ' of ' + (s.total || 0) + ' claims', usage: usageOf(pv) });

  const judged = claims.filter(c => c.judge);
  const jd = by('judge');
  steps.push({ who: 'Thomas', at, text: 'Judged ' + judged.length + ' excerpt(s) blind: ' + judged.filter(c => c.judge === 'supports').length + ' supported', usage: usageOf(jd) });

  const parts = [(s.verified || 0) + ' verified'];
  if (s.reported) parts.push(s.reported + ' reported');
  parts.push((s.traditional || 0) + ' traditional', (s.disputed || 0) + ' disputed', (s.unsourced || 0) + ' unsourced');
  steps.push({ who: 'Thomas', at, text: 'Result: ' + parts.join(', ') + (s.missingNumbers ? '; ' + s.missingNumbers + ' with numbers absent from the sources' : ''), seconds: ledger.seconds });
  for (const st of steps) if (!st.usage) delete st.usage;          // a step with no measured tokens carries no usage at all
  return steps;
}

export function recordLedger({ entry, ledger, task, multi = false, logPath = LOG_PATH, now = new Date() }) {
  const at = now.toISOString();
  const p = (task && task.payload) || {};
  const log = loadLog(logPath);
  const base = p.jobId || (task && task.id) || jobIdFor(entry.n, at);
  const id = !p.jobId && multi ? base + ':' + entry.id : base;
  const job = openJob(log, { id, title: entry.n || entry.id, kind: 'check', requestedBy: p.requestedBy, at });
  for (const st of ledgerSteps(ledger, { at })) addStep(job, st);
  prune(log, { now });
  saveLog(log, logPath);
  return job;
}

// ---- Augustine's steps (article-writer: the draft of one article) ----
// draft: the draft object article-writer saves (sourcesFile, writer.attempts, attemptLog: [{ n, violations: [text], usage: { model, inputTokens, outputTokens } }],
// checks, reviewNotes, entry, length, seconds). Tokens are on the attempt that spent them, so the dollars come from scripts/pricing.json at view time.
export function writerSteps(draft, { at } = {}) {
  const steps = [];
  const sf = draft.sourcesFile || {};
  let read = 'Read Jerome\'s file: ' + (sf.pages || 0) + ' source page(s), ' + (sf.words || 0) + ' words';
  if (sf.dropped) read += '; ' + sf.dropped + ' could not be fetched again and were left out';
  if (sf.changed) read += '; ' + sf.changed + ' changed since Jerome saw ' + (sf.changed === 1 ? 'it' : 'them');
  steps.push({ who: 'Augustine', at, text: read });
  for (const a of draft.attemptLog || []) {
    const bad = (a.violations || []);
    const max = (draft.writer && draft.writer.maxAttempts) || 3;
    const text = 'Attempt ' + a.n + ' of ' + max + (bad.length
      ? ': sent back for ' + bad.length + ' rule(s): ' + bad.slice(0, 3).join('; ').slice(0, 220) + (bad.length > 3 ? '; and ' + (bad.length - 3) + ' more' : '')
      : ': passed the form checks');
    steps.push({ who: 'Augustine', at, text, usage: a.usage ? usageOf(a.usage) : undefined });
  }
  const st = (draft.checks && draft.checks.stats) || {};
  const ok = draft.checks && draft.checks.passed;
  steps.push({ who: 'Augustine', at, text: (ok ? 'Draft ready: ' : 'Draft saved but STILL FAILING the form checks: ') + (st.words || 0) + ' words in ' + (st.sections || 0) + ' sections, ' + (st.quotes || 0) + ' quotation(s), longest sentence ' + (st.maxSentence || 0) + ' words'
    + (draft.length ? ' (' + draft.length.tier + ' tier)' : '') });
  const lf = draft.lifespan;
  if (lf && (lf.age != null || lf.died)) steps.push({ who: 'Augustine', at, text: lf.age != null ? 'Age at death: ' + (lf.kind === 'exact' ? 'exactly ' : 'about ') + lf.age + ' (Born: ' + (lf.born || '?') + '; Died: ' + String(lf.died || '?').replace(/\s*\((?:at|estimated) age \d+\)\s*$/, '') + ')' : 'No age at death: ' + (lf.reason || 'unknown') });
  const fb = draft.sourceFeedback;
  if (fb) {
    const stats = draft.sourceStats || [];
    const unused = stats.filter(x => x.used === false);
    steps.push({ who: 'Augustine', at, text: 'His view of the sources: ' + (fb.amount ? fb.amount.replace(/_/g, ' ') : 'no verdict') + '; used ' + (fb.used.length || '?') + ' of ' + stats.length
      + (unused.length ? ' (unused: ' + unused.map(x => x.domain + ' ' + x.words + ' words').join(', ') + ')' : '') + (fb.gaps.length ? '; gaps: ' + fb.gaps.join('; ').slice(0, 160) : '') });
  }
  const notes = draft.reviewNotes || [];
  if (notes.length) {
    const by = {};
    for (const n of notes) by[n.kind] = (by[n.kind] || 0) + 1;
    steps.push({ who: 'Augustine', at, text: 'Review notes for Tom: ' + Object.entries(by).map(([k, v]) => v + ' ' + k).join(', '), seconds: draft.seconds });
  } else steps[steps.length - 1].seconds = draft.seconds;
  for (const s of steps) if (!s.usage) delete s.usage;
  return steps;
}

export function recordWriter({ draft, task, logPath = LOG_PATH, now = new Date() }) {
  const at = now.toISOString();
  const p = (task && task.payload) || {};
  const log = loadLog(logPath);
  const title = (draft.subject && draft.subject.name) || draft.entryId;
  const id = p.jobId || (task && task.id) || jobIdFor(title, at);
  const job = openJob(log, { id, title, kind: draft.mode === 'rewrite' ? 'rewrite' : 'new', requestedBy: p.requestedBy, at });
  for (const st of writerSteps(draft, { at })) addStep(job, st);
  prune(log, { now });
  saveLog(log, logPath);
  return job;
}

// scripts/services/authority-finder.mjs
// MODULE DATE: 2026-10-09 (Friday) · v0.1 — "Which diocese speaks for this?": find the official website of the diocese that judges an
// apparition or miracle, check the page is real, and hand it to IGNATIUS for a decision.
//
// WHY: an apparition's approval status is stated by the bishop (and, since 2024, in agreement with the Dicastery for the Doctrine of the
// Faith) of the diocese where it happened. The sources on the approved list rarely say what the bishop decided; the diocese's own
// website would. But a site that is not on the registry is never trusted automatically.
//
// WHO DECIDES: JEROME ONLY PROPOSES. Jerome asks a model (with web search) to identify the place, the diocese and its official website;
// CODE then fetches the page and checks it (it loads; it names the diocese; it reads like a church site). The result goes into a queue,
// ignatius-queue.json, marked "waiting". IGNATIUS (the judge, NOT BUILT YET) will read the queue, decide whether it is really the
// diocese's own site, and approve or reject it. Nothing in this file edits the registry, and nothing is approved here.
//
// THE QUEUE: { "version": 1, "items": [ { "id": "site-<domain>", "kind": "site_approval", "status": "waiting" | "approved" | "rejected",
//   "domain", "url", "role": "diocese" | "alternate", "diocese", "place", "country", "confidence", "verified", "checks", "note",
//   "suggestedEntry": { registry fields }, "proposedBy": "Jerome", "firstSeen", "subjects": [ { "name", "jobId", "at" } ] } ] }
//   A site already decided (approved or rejected) is never queued again. A site already waiting just gains the new subject.
//
// The model call and the page fetch are passed in (ask, fetchPage), so this file has no network code of its own.

import { readFileSync, writeFileSync, existsSync, mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

export const QUEUE_PATH = process.env.IGNATIUS_QUEUE_PATH || 'ignatius-queue.json';
export const MAX_QUEUE_ITEMS = 200;

const fold = s => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();

// Words that appear in almost every diocese's name; the rest (the place) is what the page must mention.
const GENERIC = new Set(['the', 'of', 'de', 'di', 'del', 'della', 'da', 'do', 'dos', 'das', 'du', 'des', 'la', 'le', 'el', 'los', 'las', 'and', 'y', 'e', 'et',
  'roman', 'catholic', 'diocese', 'dioceses', 'archdiocese', 'archdiocesan', 'diocesi', 'arcidiocesi', 'diocesis', 'archidiocesis', 'archdiocesis', 'arquidiocesis', 'arquidiocese', 'obispado', 'arzobispado', 'bispado', 'archbishopric', 'eparquia', 'diocese', 'dioceses',
  'bistum', 'erzbistum', 'eparchy', 'archeparchy', 'apostolic', 'vicariate', 'prelature', 'territorial', 'military', 'ordinariate', 'church',
  'holy', 'see', 'saint', 'san', 'santa', 'sao']);

export function dioceseTokens(name) {
  return fold(name).split(/[^a-z0-9]+/).filter(t => t.length >= 3 && !GENERIC.has(t));
}

// Words that make a page read like a church institution's site, in the languages the Church's sites most often use.
const CHURCH_WORDS = ['diocese', 'dioceses', 'diocesi', 'diocesis', 'archdiocese', 'bishop', 'bishops', 'archbishop', 'parish', 'parishes', 'catholic',
  'catholique', 'cattolica', 'catolica', 'catolico', 'bistum', 'bispo', 'obispo', 'vescovo', 'eveque', 'priest', 'priests', 'clergy', 'cathedral',
  'cathedrale', 'cattedrale', 'catedral', 'kirche', 'eglise', 'chiesa', 'iglesia', 'igreja', 'mass', 'sacrament', 'sacraments'];
const CHURCH_RE = new RegExp('\\b(' + CHURCH_WORDS.join('|') + ')\\b', 'g');

export function countChurchWords(text) { return (fold(text).match(CHURCH_RE) || []).length; }

export function buildPrompt(subject, label) {
  return 'You are helping a Catholic history website find the OFFICIAL website of the Catholic diocese (or archdiocese, eparchy or equivalent) whose ' +
    'bishop judges the following, because that bishop\'s own statement is the authority for its approval status.\n\n' +
    'Subject: ' + subject.name + ' (' + label + ')' + (subject.year != null ? ', about the year ' + subject.year : '') +
    (subject.region ? ', region: ' + subject.region : '') + '.\n\n' +
    'Use the search tool. Find the place where it happened, the diocese that covers that place (if the diocese changed since, the one that made the ' +
    'judgement), and that diocese\'s OWN official website. Not a parish, not a news site, not Wikipedia, not a pilgrimage blog or a private site.\n\n' +
    'Reply with ONLY this JSON and nothing else: {"place": "...", "country": "...", "diocese": "full name of the diocese", ' +
    '"official_site_url": "https://... or null if you could not find it", "alternates": ["at most 2 other OFFICIAL https addresses, such as the ' +
    'bishops\' conference or the shrine\'s own site, or an empty list"], "confidence": "high|medium|low", "note": "one short line"}';
}

// Pull the JSON object out of a model reply (it may arrive in a code fence or with a sentence around it).
export function parseReply(text) {
  const s = String(text || '').replace(/```(?:json)?/gi, '');
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a === -1 || b <= a) throw new Error('the reply had no JSON object');
  let o;
  try { o = JSON.parse(s.slice(a, b + 1)); } catch (e) { throw new Error('the reply was not valid JSON'); }
  const str = v => (typeof v === 'string' && v.trim() ? v.trim().slice(0, 200) : '');
  const conf = ['high', 'medium', 'low'].includes(String(o.confidence).toLowerCase()) ? String(o.confidence).toLowerCase() : 'low';
  return {
    place: str(o.place), country: str(o.country), diocese: str(o.diocese),
    official_site_url: str(o.official_site_url) && !/^null$/i.test(str(o.official_site_url)) ? str(o.official_site_url) : '',
    alternates: Array.isArray(o.alternates) ? o.alternates.map(str).filter(Boolean).slice(0, 2) : [],
    confidence: conf, note: str(o.note)
  };
}

// Fetch the page and check it: it loads, it names the diocese's place, and it reads like a church site.
export async function verifySite({ url, diocese, fetchPage }) {
  const f = await fetchPage(url);
  if (!f || !f.ok) return { verified: false, http: f ? f.http : 0, dioceseMentions: 0, churchWords: 0, note: (f && f.note) || 'could not be fetched' };
  const text = fold(f.text);
  const toks = dioceseTokens(diocese);
  const dioceseMentions = toks.reduce((n, t) => n + (text.match(new RegExp('\\b' + t + '\\b', 'g')) || []).length, 0);
  const churchWords = countChurchWords(f.text);
  const problems = [];
  if (!toks.length) problems.push('the diocese name has no distinctive word to look for');
  else if (dioceseMentions < 1) problems.push('the page never names the diocese (' + toks.join(', ') + ')');
  if (churchWords < 3) problems.push('the page has only ' + churchWords + ' church words');
  return { verified: problems.length === 0, http: f.http, dioceseMentions, churchWords, ...(problems.length ? { note: problems.join('; ') } : {}) };
}

// The registry fields Ignatius would add if he approves. Never written by this file.
export function suggestedEntry({ domain, diocese, subject }) {
  return {
    domain, tier: 'official', enabled: true, group: '-', operator: diocese || domain,
    why: 'The diocese\'s own website: the body whose bishop judges ' + subject.name + ' in its territory, speaking about itself.',
    useFor: 'Its own decisions, decrees, statements and history about ' + subject.name + ' and its diocese.',
    limits: 'An institution speaking about itself: authoritative for its own decisions, not independent confirmation, and no use for general history or for other dioceses.'
  };
}

// Ask, check, and report. helpers: { safeUrl, regEntry, neverHosts }. cfg: { maxSearches, maxCandidates }.
export async function findAuthority({ subject, label, ask, fetchPage, reg, helpers, cfg = {} }) {
  const reply = await ask({ prompt: buildPrompt(subject, label), maxUses: cfg.maxSearches || 2 });
  const searches = (reply && reply.searches) || 0;
  let r;
  try { r = parseReply(reply && reply.text); } catch (e) { return { found: false, error: e.message, searches }; }
  const urls = [r.official_site_url, ...r.alternates].filter(Boolean).slice(0, cfg.maxCandidates || 3);
  const seen = new Set();
  const candidates = [];
  for (let i = 0; i < urls.length; i++) {
    const url = helpers.safeUrl(urls[i]);
    if (!url) { candidates.push({ url: urls[i], domain: '', role: i === 0 ? 'diocese' : 'alternate', registry: 'blocked', note: 'not a plain https address on a real host' }); continue; }
    const host = new URL(url).hostname.toLowerCase();
    const domain = host.replace(/^www\./, '');
    if (seen.has(domain)) continue;
    seen.add(domain);
    const role = i === 0 ? 'diocese' : 'alternate';
    if (helpers.neverHosts.some(d => host === d || host.endsWith('.' + d))) { candidates.push({ url, domain, role, registry: 'blocked', note: 'a never-allowed kind of site' }); continue; }
    const e = helpers.regEntry(reg, host);
    if (e) { candidates.push({ url, domain, role, registry: e.enabled === false ? 'disabled' : 'approved', ...(e.tier ? { tier: e.tier } : {}) }); continue; }
    const v = await verifySite({ url, diocese: r.diocese, fetchPage });
    candidates.push({ url, domain, role, registry: 'new', verified: v.verified,
      checks: { http: v.http, dioceseMentions: v.dioceseMentions, churchWords: v.churchWords }, ...(v.note ? { note: v.note } : {}),
      suggestedEntry: suggestedEntry({ domain, diocese: r.diocese, subject }) });
  }
  return { found: candidates.length > 0, place: r.place, country: r.country, diocese: r.diocese, confidence: r.confidence, ...(r.note ? { note: r.note } : {}), candidates, searches };
}

// ---- the queue for Ignatius ----
export function loadQueue(path = QUEUE_PATH) {
  try { const q = JSON.parse(readFileSync(path, 'utf8')); if (q && Array.isArray(q.items)) return q; } catch (_e) { /* start fresh */ }
  return { version: 1, items: [] };
}
export function saveQueue(q, path = QUEUE_PATH) { mkdirSync(dirname(path) || '.', { recursive: true }); writeFileSync(path, JSON.stringify(q, null, 1) + '\n'); }

// Items for the NEW sites in an authority result. ctx: { subject: { name }, jobId, at }.
export function queueItemsFor(authority, ctx) {
  if (!authority || !authority.candidates) return [];
  return authority.candidates.filter(c => c.registry === 'new').map(c => ({
    id: 'site-' + c.domain, kind: 'site_approval', status: 'waiting', domain: c.domain, url: c.url, role: c.role,
    diocese: authority.diocese, place: authority.place, country: authority.country, confidence: authority.confidence,
    verified: !!c.verified, checks: c.checks, ...(c.note ? { note: c.note } : {}), suggestedEntry: c.suggestedEntry, proposedBy: 'Jerome',
    firstSeen: ctx.at, subjects: [{ name: ctx.subject.name, jobId: ctx.jobId, at: ctx.at }]
  }));
}

// Add items. A site Ignatius has already decided is left alone; a site already waiting only gains the new subject.
export function addToQueue(queue, items) {
  let added = 0, merged = 0, skipped = 0;
  for (const it of items) {
    const ex = queue.items.find(x => x.id === it.id);
    if (!ex) { queue.items.push(it); added++; continue; }
    if (ex.status !== 'waiting') { skipped++; continue; }
    for (const s of it.subjects) if (!ex.subjects.some(y => y.name === s.name && y.jobId === s.jobId)) ex.subjects.push(s);
    if (it.verified && !ex.verified) { ex.verified = true; ex.checks = it.checks; delete ex.note; }
    merged++;
  }
  if (queue.items.length > MAX_QUEUE_ITEMS) {
    const waiting = queue.items.filter(x => x.status === 'waiting'), decided = queue.items.filter(x => x.status !== 'waiting');
    queue.items = [...decided.slice(-(MAX_QUEUE_ITEMS - waiting.length > 0 ? MAX_QUEUE_ITEMS - waiting.length : 0)), ...waiting];
  }
  return { queue, added, merged, skipped };
}

// scripts/services/registry-dates.mjs
// MODULE DATE: 2026-10-09 (Friday) · v0.2 — "When was this site approved?": the date and the person on every source in the registry.
//
// WHAT TOM ASKED FOR: on the page that lists the approved websites with all their descriptions (SOURCE-ALLOWLIST.md, generated from
// scripts/ledger-allowlist.json), show the date each site was approved and added to the list.
//
// THE FIELDS (on every entry of scripts/ledger-allowlist.json):
//   "addedAt":    "YYYY-MM-DD"  the day the site was first put on the list (even if switched off); null when it cannot be known
//   "approvedAt": "YYYY-MM-DD"  the day the site was approved, i.e. first enabled, so the ledger may use it; null for a site that is only listed
//   "approvedBy": "Tom" | "Ignatius" | ...  who approved it; null when it was not recorded
//   (the existing "vetted" note is a different thing: when and how the operator was CHECKED, not when the site was approved.)
//
// THREE JOBS:
//   1. BACKFILL the sites that were added before dates were recorded. The only honest source is the repo's own history: addedAt = the first commit whose
//      copy of the registry contains the domain; approvedAt = the first commit where it was also enabled (a site listed but switched off has no
//      approvedAt). That needs the full git history, so it runs in a workflow (registry-dates.yml).
//      approvedBy stays null: the person who committed a file is not necessarily the person who approved the site.
//   2. STAMP every future approval: stampApproval / entryFromQueueItem / addApproved are what Ignatius (not built yet) calls when he approves a site
//      from ignatius-queue.json, and what anyone adding a site by hand should use, so the date is never forgotten.
//   3. SHOW it: updateDoc adds an "Approved" column to the descriptions page (every table whose columns are Domain, Operator, ...), refreshes the
//      date in the page header, and is safe to run again.
//
// COMMAND LINE (run by .github/workflows/registry-dates.yml, which checks out the full history):
//   node scripts/services/registry-dates.mjs --backfill [--registry scripts/ledger-allowlist.json] [--doc SOURCE-ALLOWLIST.md] [--dry]
// It rewrites the registry in its own format (one-space indent) and prints how many entries it dated. Nothing is changed for entries that already
// have an approvedAt.

import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { spawnSync } from 'node:child_process';
import { pathToFileURL } from 'node:url';

export const REGISTRY_PATH = 'scripts/ledger-allowlist.json';
export const DOC_PATH = 'SOURCE-ALLOWLIST.md';
const WEEKDAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];

export const isDate = s => typeof s === 'string' && /^\d{4}-\d\d-\d\d$/.test(s) && !Number.isNaN(Date.parse(s));
export const dayOf = d => (d instanceof Date ? d : new Date(d)).toISOString().slice(0, 10);

// ---- 1. dates from the repo's own history ----
const defaultGit = args => {
  const r = spawnSync('git', args, { encoding: 'utf8', maxBuffer: 256 * 1024 * 1024 });
  if (r.status !== 0) throw new Error('git ' + args.slice(0, 2).join(' ') + ' failed: ' + String(r.stderr || '').slice(0, 200));
  return r.stdout;
};

// Map of domain -> { date, approved, sha, author }: `date` is the day of the FIRST commit whose copy of the registry contains the domain (when it
// was put on the list); `approved` is the day of the first commit where it was also enabled (null if never). runGit(argsArray) returns stdout;
// it is injected so tests can use a temporary repository.
export function datesFromHistory({ file = REGISTRY_PATH, runGit = defaultGit } = {}) {
  const log = runGit(['log', '--reverse', '--format=%H|%aI|%an', '--', file]).split('\n').filter(Boolean);
  const first = new Map();
  for (const line of log) {
    const [sha, iso, ...rest] = line.split('|');
    let reg;
    try { reg = JSON.parse(runGit(['show', sha + ':' + file])); } catch (_e) { continue; }        // an unreadable old version is skipped
    for (const e of (reg && reg.domains) || []) {
      if (!e || !e.domain) continue;
      const day = iso.slice(0, 10);
      let h = first.get(e.domain);
      if (!h) { h = { date: day, approved: null, sha, author: rest.join('|') }; first.set(e.domain, h); }
      if (e.enabled !== false && !h.approved) h.approved = day;
    }
  }
  return first;
}

// Give every entry that lacks them an addedAt and approvedAt from history. A site that is switched off is only listed, so it gets no approvedAt.
// Returns { approved, listedOnly, unknown, kept }.
export function backfill(reg, history) {
  let approved = 0, listedOnly = 0, unknown = 0, kept = 0;
  for (const e of reg.domains) {
    const h = history.get(e.domain);
    if (!isDate(e.addedAt)) e.addedAt = h ? h.date : null;
    if (isDate(e.approvedAt)) kept++;
    else if (e.enabled === false) { e.approvedAt = null; listedOnly++; }
    else if (h && (h.approved || h.date)) { e.approvedAt = h.approved || h.date; approved++; }
    else { e.approvedAt = null; unknown++; }
    if (!('approvedBy' in e)) e.approvedBy = null;
  }
  reg.datesNote = 'addedAt is the day a site was put on this list; approvedAt is the day it was approved (first enabled), null while it is only listed. For sites added before 2026-10-09 both come from the first commit of this file that contained the domain (and had it enabled); approvedBy was not recorded then. null means unknown or not approved.';
  return { approved, listedOnly, unknown, kept };
}

// ---- 2. stamping approvals ----
export function stampApproval(entry, { by, at }) {
  if (!by || !String(by).trim()) throw new Error('an approval needs to say who approved it');
  entry.addedAt = isDate(entry.addedAt) ? entry.addedAt : dayOf(at);
  entry.approvedAt = dayOf(at);
  entry.approvedBy = String(by).trim();
  return entry;
}

// The registry entry for a site Ignatius has approved from the queue (an item of ignatius-queue.json).
export function entryFromQueueItem(item, { by, at }) {
  if (!item || !item.suggestedEntry || !item.suggestedEntry.domain) throw new Error('this queue item has no suggested registry entry');
  const day = dayOf(at);
  const e = { ...item.suggestedEntry, enabled: true };
  e.vetted = 'proposed by ' + (item.proposedBy || 'Jerome') + ' ' + String(item.firstSeen || '').slice(0, 10) + '; judged and approved by ' + by + ' ' + day +
    (item.verified ? '; the page was checked: it loads, names the diocese and reads like a church site' : '; the page could NOT be confirmed as a church site by the code check');
  return stampApproval(e, { by, at });
}

// Add an approved entry to the registry (never replaces an existing domain) and mark the file as updated that day.
export function addApproved(reg, entry, { at }) {
  if (!isDate(entry.approvedAt) || !entry.approvedBy) throw new Error('only a stamped entry can be added (approvedAt and approvedBy)');
  if (reg.domains.some(e => e.domain === entry.domain)) throw new Error(entry.domain + ' is already in the registry');
  reg.domains.push(entry);
  reg.updated = dayOf(at);
  return reg;
}

// ---- 3. the descriptions page ----
export const approvalText = e => !e || !isDate(e.approvedAt) ? 'date not recorded'
  : e.approvedAt + (e.approvedBy ? ' by ' + e.approvedBy : '') + (isDate(e.addedAt) && e.addedAt !== e.approvedAt ? ' (listed ' + e.addedAt + ')' : '');

const cells = line => line.trim().replace(/^\|/, '').replace(/\|$/, '').split('|').map(c => c.trim());
const row = cs => '| ' + cs.join(' | ') + ' |';

export function updateDoc(md, reg, { now = new Date() } = {}) {
  const byDomain = new Map(reg.domains.map(e => [e.domain, e]));
  const lines = md.split('\n');
  const out = [];
  let i = 0, tables = 0, rows = 0;
  while (i < lines.length) {
    if (!lines[i].trim().startsWith('|')) { out.push(lines[i]); i++; continue; }
    let j = i;
    while (j < lines.length && lines[j].trim().startsWith('|')) j++;
    const block = lines.slice(i, j), head = cells(block[0]);
    if (head[0] === 'Domain' && head[1] === 'Operator' && head.length >= 6) {
      tables++;
      const has = head[head.length - 1] === 'Approved';
      block.forEach((ln, k) => {
        const cs = cells(ln);
        if (k === 0) { if (!has) cs.push('Approved'); }
        else if (k === 1) { if (!has) cs.push('---'); }
        else {
          const dom = (cs[0] || '').replace(/`/g, '');
          const txt = approvalText(byDomain.get(dom));
          if (has) cs[cs.length - 1] = txt; else cs.push(txt);
          rows++;
        }
        out.push(row(cs));
      });
    } else out.push(...block);
    i = j;
  }
  let text = out.join('\n');
  const day = dayOf(now), wd = WEEKDAYS[new Date(day + 'T12:00:00Z').getUTCDay()];
  text = text.replace(/DOC DATE: \d{4}-\d\d-\d\d \([A-Za-z]+\)/, 'DOC DATE: ' + day + ' (' + wd + ')');
  const note = ' Each entry also records the day it was approved and added to the list (`approvedAt`) and who approved it (`approvedBy`); the Approved column shows both.';
  if (!text.includes('`approvedAt`')) text = text.replace(/(\n5\. \*\*Checked, and dated\.\*\*[^\n]*)/, '$1' + note);
  return { text, tables, rows };
}

// ---- command line ----
function readJson(path) { const raw = readFileSync(path, 'utf8'); return { reg: JSON.parse(raw), trailingNewline: raw.endsWith('\n') }; }
export const writeRegistry = (path, reg, trailingNewline) => writeFileSync(path, JSON.stringify(reg, null, 1) + (trailingNewline ? '\n' : ''));

function main(argv) {
  const get = f => { const i = argv.indexOf(f); return i >= 0 ? argv[i + 1] : null; };
  if (!argv.includes('--backfill')) { console.error('usage: registry-dates.mjs --backfill [--registry path] [--doc path] [--dry]'); return 2; }
  const regPath = get('--registry') || REGISTRY_PATH, docPath = get('--doc') || DOC_PATH, dry = argv.includes('--dry');
  const { reg, trailingNewline } = readJson(regPath);
  const history = datesFromHistory({ file: regPath });
  const r = backfill(reg, history);
  console.log('registry: ' + reg.domains.length + ' entries; approval dated from history: ' + r.approved + '; already dated: ' + r.kept + '; listed only (switched off): ' + r.listedOnly + '; date unknown: ' + r.unknown);
  if (r.unknown) console.log('unknown: ' + reg.domains.filter(e => e.enabled !== false && !isDate(e.approvedAt)).map(e => e.domain).join(', '));
  if (!dry) writeRegistry(regPath, reg, trailingNewline);
  if (existsSync(docPath)) {
    const d = updateDoc(readFileSync(docPath, 'utf8'), reg);
    console.log('doc: ' + d.tables + ' table(s), ' + d.rows + ' row(s) now show the approval date');
    if (!dry) writeFileSync(docPath, d.text);
  } else console.log('doc: ' + docPath + ' not found, skipped');
  return 0;
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) process.exit(main(process.argv.slice(2)));

// scripts/services/sources-file.mjs
// MODULE DATE: 2026-10-09 (Friday) · v0.1 — sources/<entry-id>.json: what Jerome hands to the writer (Augustine) and the verifier (Thomas).
//
// WHY: Jerome's work was only visible in a log and in a task result. The rest of the pipeline needs the same four pages, by name, per entry.
// This is the interface between Jerome and everything after him. It follows the storage rules decided on 2026-10-07 (design doc, sections 9-10):
//   - ONE FILE PER ENTRY: sources/<entry-id>.json (the id is the timeline's own id, e.g. st-augustine-430; for a new subject, slug of name + year).
//   - EVERY selected page gets a manifest line: url, title, domain, tier, lane, words, hash, when it was fetched, and how it ranked.
//   - FULL TEXT IS STORED ONLY WHERE TOM HAS SET THE REGISTRY ENTRY'S "storage" TO "full" (public domain, e.g. newadvent.org, ccel.org). The default is
//     "excerpts": no text in the file, and whoever needs the page (Augustine, Thomas) fetches it again, which is free, and checks the hash.
//     Scripture is NEVER stored whatever the setting says.
//   - Pages that could make the material enough but are not approved yet are listed as "unsure" (a manifest only) for Ignatius.
//
// FILE (version 1):
//   { version, entryId, mode: "new" | "rewrite", subject: { name, category, year }, builtAt, finder, jobId, model,
//     outcome: "ready" | "needs_decision" | "too_thin" | "not_found",   reason, flags[],
//     verdict: { action, basis, reasons[], advisory[] }, perspectives: { covered[], missing[] }, authority?: { diocese, place, country, candidates[] },
//     totalWords,                                  words in the selected pages
//     sources: [ { n, url, title, domain, tier, lane, canVerify, status: "approved", fetchedAt, words, mentions, score, hash, storage, text? } ],
//     unsure:  [ { url, domain, words, mentions } ],
//     alsoFound: [ { url, domain, lane, words, score } ] }
//
// READING IT: getSourceTexts(file, { fetchPage }) returns each source's text (stored, or fetched again) with a drift note when a fetched page no
// longer matches its hash. A page that has changed is still returned, flagged "changed", because the web moves; one that cannot be fetched is
// flagged "unavailable" and carries no text, so the caller can stop instead of writing from nothing.

import { readFileSync, writeFileSync, existsSync, mkdirSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { join, dirname } from 'node:path';

export const SOURCES_DIR = process.env.SOURCES_DIR || 'sources';

// The same fingerprint Jerome puts on a fetched page: the first 16 hex characters of the SHA-256 of its cleaned text.
export const hashText = text => createHash('sha256').update(String(text)).digest('hex').slice(0, 16);

const slug = s => String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');

// An id safe to use as a file name. Throws on anything else, so a bad id can never reach outside the folder.
export function safeId(id) {
  const s = String(id || '');
  if (!/^[a-z0-9][a-z0-9-]{0,100}$/.test(s)) throw new Error('not a valid entry id for a sources file: "' + s.slice(0, 60) + '"');
  return s;
}

// The timeline's own id for an existing entry, or slug(name)-year for a new subject (the app's rule).
export function entryIdFor(subject) {
  if (subject && subject.id) return safeId(subject.id);
  const base = slug(subject && subject.name);
  if (!base) throw new Error('cannot make an entry id without a name');
  return safeId(subject.year != null ? base + '-' + subject.year : base);
}

export const sourcesPath = (id, dir = SOURCES_DIR) => join(dir, safeId(id) + '.json');

// storageOf(domain, tier) -> "full" | "excerpts". Scripture never, whatever the setting.
function storageFor(src, storageOf) {
  if (src.tier === 'scripture') return 'excerpts';
  return storageOf && storageOf(src.domain) === 'full' ? 'full' : 'excerpts';
}

// Build the file from a RAW source-finder result (the one that still carries the per-page records, and, in memory only, each page's text).
// opts: { task, now, finder, storageOf(domain) }
export function buildSourcesFile(result, opts = {}) {
  const L3 = result && result.layer3;
  if (!L3 || !L3.selection) throw new Error('this result has no selection to save (no search was run)');
  const task = opts.task || {};
  const p = task.payload || {};
  const subject = result.subject || {};
  const byUrl = new Map(((result.search && result.search.sources) || []).map(s => [s.url, s]));
  const sel = L3.selection.selected || [];
  const sources = sel.map((x, i) => {
    const raw = byUrl.get(x.url) || {};
    const storage = storageFor({ domain: raw.domain || x.domain, tier: x.tier }, opts.storageOf);
    const s = { n: i + 1, url: x.url, title: raw.title || x.title || '', domain: String(x.domain || raw.domain || '').replace(/^www\./, ''), tier: x.tier || null, lane: x.lane || null,
      canVerify: !!x.canVerify, status: 'approved', fetchedAt: raw.fetchedAt || null, words: x.words, mentions: x.mentions, score: x.score, hash: raw.hash || null, storage };
    if (storage === 'full' && raw.plain) s.text = raw.plain;
    return s;
  });
  const unsure = ((L3.decisions || []).find(d => d.kind === 'unjudged_sources') || { urls: [] }).urls
    .map(u => byUrl.get(u)).filter(Boolean).map(r => ({ url: r.url, domain: String(r.domain || '').replace(/^www\./, ''), words: r.words, mentions: r.mentions }));
  const a = result.authority;
  const file = {
    version: 1,
    entryId: entryIdFor({ id: subject.id, name: subject.name || p.name, year: subject.year != null ? subject.year : p.year }),
    mode: result.mode === 'rewrite' ? 'rewrite' : 'new',
    subject: { name: subject.name || p.name || null, category: subject.category || p.category || null, year: subject.year != null ? subject.year : (p.year != null ? p.year : null) },
    builtAt: (opts.now || new Date()).toISOString(), finder: opts.finder || 'source-finder', jobId: opts.jobId || p.jobId || task.id || null,
    model: (result.timing && result.timing.model) || null,
    outcome: L3.status, ...(L3.reason ? { reason: L3.reason } : {}), flags: L3.flags || [],
    verdict: L3.verdict ? { action: L3.verdict.action, basis: L3.verdict.basis || null, reasons: L3.verdict.reasons || [], ...(L3.verdict.advisory ? { advisory: L3.verdict.advisory } : {}) } : null,
    ...(L3.perspectives ? { perspectives: { covered: L3.perspectives.covered.map(c => c.id), missing: L3.perspectives.missing } } : {}),
    ...(a && a.found ? { authority: { diocese: a.diocese, place: a.place, country: a.country, candidates: a.candidates.map(c => ({ domain: c.domain, role: c.role, registry: c.registry, ...(c.verified != null ? { verified: c.verified } : {}) })) } } : {}),
    totalWords: sources.reduce((n, s) => n + (s.words || 0), 0),
    sources, unsure,
    alsoFound: (L3.selection.alsoFound || []).map(x => ({ url: x.url, domain: String(x.domain || '').replace(/^www\./, ''), lane: x.lane || null, words: x.words, score: x.score }))
  };
  return file;
}

export function writeSourcesFile(file, dir = SOURCES_DIR) {
  const path = sourcesPath(file.entryId, dir);
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, JSON.stringify(file, null, 1) + '\n');
  return path;
}

export function loadSources(id, dir = SOURCES_DIR) {
  const path = sourcesPath(id, dir);
  if (!existsSync(path)) return null;
  const f = JSON.parse(readFileSync(path, 'utf8'));
  if (!f || f.version !== 1 || !Array.isArray(f.sources)) throw new Error('sources file ' + path + ' is not version 1');
  return f;
}

// The text of each source: stored, or fetched again with a drift note. fetchPage(url) -> { ok, text, http, note }.
export async function getSourceTexts(file, { fetchPage }) {
  const out = [];
  for (const s of file.sources) {
    const base = { n: s.n, url: s.url, domain: s.domain, tier: s.tier, lane: s.lane, canVerify: s.canVerify };
    if (typeof s.text === 'string' && s.text) { out.push({ ...base, text: s.text, drift: 'stored' }); continue; }
    let f;
    try { f = await fetchPage(s.url); } catch (e) { f = { ok: false, note: String((e && e.message) || e).slice(0, 120) }; }
    if (!f || !f.ok || !f.text) { out.push({ ...base, text: '', drift: 'unavailable', note: (f && f.note) || 'could not be fetched' }); continue; }
    const same = s.hash && hashText(f.text) === s.hash;
    const words = f.text.split(/\s+/).filter(Boolean).length;
    out.push({ ...base, text: f.text, drift: same ? 'same' : 'changed', ...(same ? {} : { note: 'the page differs from the one Jerome chose (' + (s.words || '?') + ' words then, about ' + words + ' now)' }) });
  }
  return out;
}

// scripts/services/registry.mjs
// MODULE DATE: 2026-10-09 (Friday) · v0.1 — ONE reader for the source registry, scripts/ledger-allowlist.json.
//
// Jerome (source-finder) and Thomas (ledger-build) must agree on which sites count and at what tier, so both read the registry through this file.
// It only reads; the registry is edited by hand or by an approval (scripts/services/registry-dates.mjs), never from here.
//
// Registry shape: { tiers: { <tier>: { canVerify, ceiling, ... } }, domains: [ { domain, tier, enabled, ... } ] }
// A domain with enabled:false is LISTED but not approved. A tier with canVerify:false (e.g. "reported") can be used as a source, but a match on it can
// only ever be called "reported", never "verified".

import { existsSync, readFileSync } from 'node:fs';

// Read at call time, so a test (or a one-off run) can point to another file with LEDGER_ALLOWLIST_PATH.
export const allowlistPath = () => process.env.LEDGER_ALLOWLIST_PATH || 'scripts/ledger-allowlist.json';

export function loadRegistry(path = allowlistPath()) {
  if (!existsSync(path)) throw new Error('allowlist registry not found at ' + path + ' (commit scripts/ledger-allowlist.json first)');
  const r = JSON.parse(readFileSync(path, 'utf8'));
  if (!(r && r.tiers && Array.isArray(r.domains))) throw new Error('allowlist registry at ' + path + ' is not in the expected shape');
  return r;
}

// Most specific registry entry for a host (bible.usccb.org beats usccb.org).
export function regEntry(reg, host) {
  let best = null;
  for (const e of reg.domains) {
    if (host === e.domain || host.endsWith('.' + e.domain)) { if (!best || e.domain.length > best.domain.length) best = e; }
  }
  return best;
}

// scripts/services/article-checks.mjs
// MODULE DATE: 2026-10-09 (Friday) · v0.1 — the checks CODE makes on a draft article, before it goes to Thomas or to Tom.
//
// Pure functions, no network. They enforce the rules in scripts/writer-rules.md (an excerpt of content-authoring-skill.md) that can be checked
// mechanically, so Augustine is not trusted to follow them and the work is not done by a model:
//   - no sentence over 40 words (the same limit the sentence-reword service enforces), average around 18-22 (reported, not enforced)
//   - the length tier: standard 600-750, major 900-1000 (never more than 1,000), lesser 400-600 words; a short article is allowed only when the sources are thin
//   - dates in American order, no ordinals, en dash in ranges, "c." not "circa" (quotations are exempt)
//   - quotations are word for word in a source, and attributed
//   - Quick Facts use the labels for the entry's type; an age at death is in one of the two allowed forms
//   - words that appear too often (scripts/writer-style.json), counted in the sections and the short description
//   - only the HTML tags the app allows
// Nothing here judges whether a fact is TRUE; that is Thomas's job (ledger-build).

export const wordCount = s => String(s || '').trim().split(/\s+/).filter(Boolean).length;

// ---- text helpers ----
export const stripTags = s => String(s || '').replace(/<br\s*\/?>/gi, ' ').replace(/<\/(p|li|blockquote)>/gi, '. ').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim();

// Words that end in a full stop without ending a sentence.
const ABBREV = ['St', 'Sts', 'Fr', 'Mt', 'Mr', 'Mrs', 'Ms', 'Dr', 'Jr', 'Sr', 'Bl', 'Bp', 'Abp', 'Msgr', 'Rev', 'Gen', 'Capt', 'vs', 'No', 'Nos', 'Vol', 'ch', 'cf', 'ca', 'c', 'e.g', 'i.e', 'a.m', 'p.m', 'A.D', 'B.C', 'Ps', 'Mt', 'Lk', 'Jn', 'Mk', 'Acts'];
const PLACE = '\u0001';

export function splitSentences(text) {
  let t = stripTags(text);
  for (const a of ABBREV) t = t.replace(new RegExp('\\b' + a.replace(/\./g, '\\.') + '\\.(?=\\s)', 'g'), a + PLACE);
  t = t.replace(/\b([A-Z])\.(?=\s+[A-Z])/g, '$1' + PLACE);                                   // initials: J. R. R.
  return t.split(/(?<=[.!?])["\u201D\u2019)]*\s+(?=["\u201C\u2018(]?[A-Z0-9])/).map(s => s.replace(new RegExp(PLACE, 'g'), '.').trim()).filter(Boolean);
}

export function sentenceReport(text, maxWords = 40) {
  const ss = splitSentences(text);
  const lens = ss.map(wordCount);
  const over = ss.filter((_s, i) => lens[i] > maxWords).map(s => ({ words: wordCount(s), text: s.slice(0, 120) + (s.length > 120 ? '…' : '') }));
  return { count: ss.length, over, max: Math.max(0, ...lens), avg: ss.length ? Math.round((lens.reduce((a, b) => a + b, 0) / ss.length) * 10) / 10 : 0 };
}

// Remove quotations so that rules which do not apply inside them are not checked there.
const outsideQuotes = s => String(s || '').replace(/\u201C[^\u201D]*\u201D/g, ' ').replace(/"[^"]*"/g, ' ');

const MONTHS = 'January|February|March|April|May|June|July|August|September|October|November|December';
export function dateViolations(text) {
  const t = outsideQuotes(stripTags(text));
  const out = [];
  const add = (rule, re) => { for (const m of t.matchAll(re)) out.push({ rule, text: m[0] }); };
  add('day before month (write "December 28")', new RegExp('\\b\\d{1,2}(?:st|nd|rd|th)?\\s+(?:of\\s+)?(?:' + MONTHS + ')\\b', 'g'));
  add('ordinal on a date (write "December 28", not "28th")', new RegExp('\\b(?:' + MONTHS + ')\\s+\\d{1,2}(?:st|nd|rd|th)\\b', 'g'));
  add('"circa"/"ca." (write "c. 1020")', /\b(?:circa|ca\.)\s*\d+/gi);
  add('numeric date (write the month in words)', /\b\d{1,2}\/\d{1,2}\/\d{2,4}\b/g);
  add('hyphen in a date range (use an en dash)', new RegExp('\\b(?:' + MONTHS + ')\\s+\\d{1,2}-\\d{1,2}\\b', 'g'));
  return out;
}

// ---- words used too often ----
export function styleViolations(text, limits) {
  const t = stripTags(text);
  const out = [];
  for (const l of limits || []) {
    let re;
    try { re = new RegExp(l.pattern, 'gi'); } catch (_e) { continue; }
    const n = (t.match(re) || []).length;
    if (n > l.maxPerArticle) out.push({ id: l.id, count: n, max: l.maxPerArticle, why: l.why || '', instead: Array.isArray(l.instead) ? l.instead : [] });
  }
  return out;
}

// ---- HTML ----
const ALLOWED_TAGS = new Set(['b', 'i', 'u', 'ul', 'ol', 'li', 'br', 'blockquote', 'a']);
export function htmlViolations(html) {
  const out = [];
  for (const m of String(html || '').matchAll(/<\/?\s*([a-zA-Z][a-zA-Z0-9]*)([^>]*)>/g)) {
    const tag = m[1].toLowerCase();
    if (!ALLOWED_TAGS.has(tag)) out.push('tag <' + tag + '> is not allowed');
    else if (tag === 'a' && !/^<\s*\//.test(m[0]) && !/href\s*=\s*["']https:\/\//i.test(m[2])) out.push('a link must have an https href');
    if (tag === 'a' && /href\s*=\s*["']entry:/i.test(m[2])) out.push('entry: links are not written by the writer');
  }
  return [...new Set(out)];
}

// ---- length tiers ----
export const BANDS = { major: { min: 900, max: 1000 }, standard: { min: 600, max: 750 }, lesser: { min: 400, max: 600 } };

// payload.length wins; otherwise the entry's explicit tier (1 major, 2 standard, 3 lesser); otherwise standard. Thin sources only ever lower the band.
export function lengthTier({ requested, entryTier, sourceWords }) {
  let tier = ['major', 'standard', 'lesser'].includes(requested) ? requested : ({ 1: 'major', 2: 'standard', 3: 'lesser' }[entryTier] || 'standard');
  if (!requested && sourceWords != null && sourceWords < 2500) tier = 'lesser';
  else if (!requested && sourceWords != null && sourceWords < 4500 && tier === 'major') tier = 'standard';
  return { tier, ...BANDS[tier] };
}

// ---- quotations ----
const foldQuote = s => String(s || '').normalize('NFC').replace(/[\u2018\u2019\u201A\u2032]/g, "'").replace(/[\u201C\u201D\u201E\u2033]/g, '"').replace(/[\u2013\u2014\u2212]/g, '-')
  .replace(/\u00A0/g, ' ').replace(/\s+/g, ' ').trim().toLowerCase();
// Is this quotation, word for word (apart from quote marks, dashes, spacing and case), in one of the source texts? Returns the source's n or 0.
export function quoteSource(quote, sources) {
  const q = foldQuote(quote).replace(/^["']|["']$/g, '');
  if (q.length < 8) return 0;
  for (const s of sources) if (foldQuote(s.text).includes(q)) return s.n;
  return 0;
}

// ---- Quick Facts ----
export const FACT_LABELS = {
  s: ['Feast day', 'Born', 'Died', 'Title', 'Beatified', 'Canonized', 'Patronage', 'Religious order', 'Major works', 'Attributes in art'],
  c: ['Ecumenical number', 'Convoked by', 'Location', 'Dates', 'Condemned', 'Defined', 'Key documents', 'Sessions'],
  p: ['Regime or ruler', 'Region', 'Span of years', 'Cause', 'Notable martyrs', 'Estimated toll', 'Ended by'],
  m: ['Seer(s)', 'Location', 'Date(s)', 'Title of Our Lady', 'Words/message', 'Approval status', 'Feast day', 'Shrine'],
  u: ['Location', 'Date', 'What occurred', 'Scientific findings', 'Approval status', 'Where venerated'],
  e: ['Date', 'Location', 'Key figures', 'Significance', 'Related document or decree']
};

export function factViolations(type, facts) {
  const out = [];
  const allowed = FACT_LABELS[type];
  const seen = new Set();
  for (const f of facts || []) {
    const label = String((f && f.label) || '').trim(), value = String((f && f.value) || '').trim();
    if (!label || !value) { out.push('a Quick Fact with an empty label or value'); continue; }
    if (allowed && !allowed.includes(label)) out.push('Quick Fact label "' + label + '" is not one of: ' + allowed.join(', '));
    if (seen.has(label)) out.push('Quick Fact "' + label + '" appears twice');
    seen.add(label);
    if (value.length > 160) out.push('Quick Fact "' + label + '" is too long (keep each value short)');
    if (label === 'Died' && /age/i.test(value) && !/\((?:at age|estimated age) \d{1,3}\)\s*$/.test(value)) out.push('"Died" age must end "(at age N)" or "(estimated age N)"');
    for (const v of dateViolations(value)) out.push('Quick Fact "' + label + '": ' + v.rule + ' ("' + v.text + '")');
  }
  return out;
}

// ---- the whole draft ----
// draft: { d, sections: [{h, b}], quotes: [{text, source}], facts: [{label, value}] }; opts: { type, band, limits, sources: [{n, text}], sourceWords }
export function checkDraft(draft, opts) {
  const v = [];
  const sections = Array.isArray(draft.sections) ? draft.sections : [];
  const body = sections.map(s => stripTags(s && s.b)).join(' ');
  const words = wordCount(body);
  const band = opts.band;

  if (sections.length < 4 || sections.length > 8) v.push({ rule: 'sections', text: 'there are ' + sections.length + ' sections; expected 5 to 7 (never fewer than 4 or more than 8)' });
  sections.forEach((s, i) => { if (!s || !String(s.h || '').trim() || !String(s.b || '').trim()) v.push({ rule: 'sections', text: 'section ' + (i + 1) + ' has no heading or no text' }); });
  if (words > band.max) v.push({ rule: 'length', text: 'the article is ' + words + ' words; the limit for this tier is ' + band.max + ' (never exceed it)' });
  const thin = opts.sourceWords != null && opts.sourceWords < 3000;
  if (words < band.min && !thin) v.push({ rule: 'length', text: 'the article is ' + words + ' words; the target for this tier is ' + band.min + ' to ' + band.max });

  const sr = sentenceReport(body, 40);
  for (const s of sr.over) v.push({ rule: 'sentence', text: s.words + ' words (limit 40): "' + s.text + '"' });
  const dsr = sentenceReport(draft.d || '', 40);
  if (!String(draft.d || '').trim()) v.push({ rule: 'description', text: 'the short description is empty' });
  else if (wordCount(draft.d) > 60) v.push({ rule: 'description', text: 'the short description is ' + wordCount(draft.d) + ' words; keep it to one or two sentences' });
  for (const s of dsr.over) v.push({ rule: 'sentence', text: 'short description sentence of ' + s.words + ' words' });

  for (const d of dateViolations(body + ' ' + (draft.d || ''))) v.push({ rule: 'date', text: d.rule + ': "' + d.text + '"' });
  for (const sv of styleViolations(body + ' ' + (draft.d || ''), opts.limits)) v.push({ rule: 'style', text: '"' + sv.id + '" appears ' + sv.count + ' times; the limit is ' + sv.max + '. Use other wording for the extra uses' + (sv.instead.length ? ', for example: ' + sv.instead.join(', ') : '') + '.' });
  sections.forEach((s, i) => { for (const h of htmlViolations(s && s.b)) v.push({ rule: 'html', text: 'section ' + (i + 1) + ': ' + h }); });
  for (const f of factViolations(opts.type, draft.facts)) v.push({ rule: 'facts', text: f });

  const quotes = Array.isArray(draft.quotes) ? draft.quotes : [];
  if (quotes.length > 4) v.push({ rule: 'quotes', text: quotes.length + ' quotations; the limit is 4' });
  quotes.forEach((q, i) => {
    if (!q || !String(q.text || '').trim()) { v.push({ rule: 'quotes', text: 'quotation ' + (i + 1) + ' is empty' }); return; }
    if (!String(q.source || '').trim()) v.push({ rule: 'quotes', text: 'quotation ' + (i + 1) + ' has no attribution' });
    if (!quoteSource(q.text, opts.sources || [])) v.push({ rule: 'quotes', text: 'quotation ' + (i + 1) + ' is not word for word in any source: "' + String(q.text).slice(0, 80) + '"' });
  });

  return { violations: v, stats: { words, sections: sections.length, sentences: sr.count, maxSentence: sr.max, avgSentence: sr.avg, quotes: quotes.length, facts: (draft.facts || []).length } };
}

// scripts/services/article-writer.mjs
// MODULE DATE: 2026-10-10 (Saturday) · v0.3 — "Augustine": writes ONE draft article from the pages Jerome saved, and nothing else.
//
// Service "article-write". It never touches data.json. It writes drafts/<entry-id>.json, which Thomas (ledger-build) checks next, then the recorder
// (Kokoro), and which Tom approves by listening and reading the review notes. Nothing goes live until he approves.
//
// TASK SHAPE:  { id, type: 'article-write', entityId: '<existing entry id>' }                          (a rewrite)
//              { id, type: 'article-write', payload: { name, category, year } }                        (a new subject)
//   payload: { model: 'claude-sonnet-5-5' (default: Tom's decision that the writer is Sonnet, the one role that does not swap models), length: 'major'|'standard'|'lesser' (default: from the entry's tier, lowered if the sources are thin),
//              override: false (true = write even though Jerome's outcome was not "ready"; a person has decided), jobId }
//
// WHAT IT DOES
//   1. Reads sources/<entry-id>.json (Jerome's handoff) and gets each page's text (stored, or fetched again). A page that cannot be fetched is left out;
//      too little left, or Jerome's outcome not "ready" (needs_decision, too_thin, not_found) and no override, and it stops with the reason: no draft.
//   2. Asks the model (Anthropic) to write the article from those pages ONLY, following scripts/writer-rules.md (an excerpt of the authoring skill) and the
//      words rationed in scripts/writer-style.json. When sources disagree he PICKS THE WINNER (higher-ranked tier first) and writes a review note naming both
//      versions and why: Tom's decision of 2026-10-09 ("pick the winner but add a note to review and I will look at it and make a final decision").
//   3. CODE checks the result (article-checks.mjs): sentence length, length tier, dates, quotations word for word in a source, Quick Fact labels, rationed words,
//      HTML. Anything wrong goes back to the model with the reason, up to 3 attempts. After the last attempt the draft is saved anyway, marked as still failing,
//      so a person sees it rather than losing it.
//   4. CODE builds the links (the pages he was given, in rank order; never a URL from the model), adds a review note for Jerome's own warnings, and for
//      apparitions and miracles always adds an "approval" note (a person must set the approval level).
//   5. Writes the draft, a step list in article-log.json (tokens per attempt, so cost is measured), and returns both to commit.
//
// AGE AT DEATH (v0.2, Tom 2026-10-09): for a saint or other person the reader wants to know whether he died old or young, so an age is given even when a date is
// a little fuzzy ("died at about seventy-five"). The model does NO arithmetic: he writes the Born and Died facts as the sources give them, and writes the marker
// [[AGE]] once where the age belongs in the story of the death. CODE (lifespan.mjs) computes the age (exact only from two full dates; otherwise estimated from the
// years, a range or "c." giving the midpoint; no age when the dates are more than 6 years apart or the birth year is unknown), puts it on the Died fact, and
// replaces the marker with "at the age of N" or "at about N" (or removes it when there is no age). A computed age is not a sourced claim: Thomas must not look
// for it in the sources.
//
// SOURCE FEEDBACK (v0.2, groundwork for the efficiency phase Tom described): the model also says whether the sources were too little, about right or too much, which
// he used, what gaps he saw and what would have helped. It is stored in the draft as `sourceFeedback`, with `sourceStats` (words, tier and used or not for each
// source), so after a pilot there is real evidence for trimming what he is sent. It never appears in the article and changes nothing yet.
//
// The model never grades itself: Thomas checks every claim afterwards, against the same pages, on different models.
//
// DRAFT FILE drafts/<entry-id>.json (version 1):
//   { version, entryId, mode: 'new'|'rewrite', status: 'draft' | 'needs_work', subject: { name, category, year }, builtAt,
//     writer: { role: 'Augustine', model, attempts, maxAttempts }, sourcesFile: { file, jobId, builtAt, outcome, pages, words, dropped, changed },
//     length: { tier, min, max },
//     entry: { id, y, n, t, r, country, alt: [], d, art: { sections: [{ h, b }], quotes: [{ text, source }], links: [{ label, url }] }, facts: [{ label, value }] },
//     reviewNotes: [ { kind: 'conflict'|'tradition'|'thin'|'approval'|'sources'|'form'|'other', note?, claim?, chosen?: { text, source }, other?: { text, source }, why? } ],
//     flaggedWords: [ plain words likely to trip the voice; NO suggested pronunciation ],
//     checks: { passed, violations: [{ rule, text }], stats }, attemptLog: [ { n, violations: [text], usage } ], usage: [ ... ], seconds }
//   `entry` holds only the fields the writer owns, plus id/y/n/t/r to identify it. On approval a person (or the approval step) merges it into data.json.
//
// Requires ANTHROPIC_API_KEY. The page text is never written to the draft.

import { readFileSync, writeFileSync, mkdirSync, existsSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { join, dirname } from 'node:path';
import { loadSources, getSourceTexts, entryIdFor, SOURCES_DIR } from './sources-file.mjs';
import { loadRegistry } from './registry.mjs';
import { checkDraft, lengthTier, wordCount } from './article-checks.mjs';
import { applyAgeToFacts, numberWords } from './lifespan.mjs';
import { recordWriter, LOG_PATH } from './article-log.mjs';
import { realFetchPage } from './source-finder.mjs';

export const DRAFTS_DIR = process.env.DRAFTS_DIR || 'drafts';
const RULES_PATH = process.env.WRITER_RULES_PATH || 'scripts/writer-rules.md';
const STYLE_PATH = process.env.WRITER_STYLE_PATH || 'scripts/writer-style.json';
const DEFAULT_MODEL = 'claude-sonnet-5-5';        // Tom, 2026-10-10: Sonnet is Augustine's model (briefly set to Opus by mistake and corrected); the other roles may swap models
const MAX_ATTEMPTS = 3;
const TOKEN_BUDGETS = [9000, 14000, 16000];
const MAX_SOURCE_CHARS = 120000;           // per page sent to the model; a longer page is cut with a note
const MIN_SOURCE_WORDS = 800;              // fewer words than this left after dropping pages: no draft
const REGIONS = ['rome', 'west', 'brit', 'east', 'holy', 'africa', 'americas', 'asia'];
const CATEGORY_LABEL = { s: 'Saint', c: 'Council', p: 'Persecution', m: 'Marian apparition', u: 'Eucharistic miracle', e: 'Event', i: 'Topic page' };
const NOTE_KINDS = ['conflict', 'tradition', 'thin', 'approval', 'sources', 'form', 'other'];
const AGE_TOKEN = '[[AGE]]';
const AMOUNTS = ['too_little', 'about_right', 'too_much'];

let tokensUsed = 0;

// ---- the model call (Anthropic Messages); deps.callModel replaces it in tests ----
async function callAnthropic({ system, user, maxTokens, model }) {
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) throw new Error('Missing ANTHROPIC_API_KEY secret (needed for the writer).');
  const res = await fetch('https://api.anthropic.com/v1/messages', {
    method: 'POST', headers: { 'x-api-key': apiKey, 'anthropic-version': '2023-06-01', 'Content-Type': 'application/json' },
    body: JSON.stringify({ model, max_tokens: maxTokens, system, messages: [{ role: 'user', content: user }] })
  });
  if (!res.ok) {
    const err = new Error('Anthropic messages ' + res.status + ': ' + String(await res.text().catch(() => '')).slice(0, 300));
    err.status = res.status;
    if (res.status === 429 || res.status === 529 || /quota|credit|billing/i.test(err.message)) err.deferred = true;
    throw err;
  }
  const data = await res.json();
  const u = data.usage || {};
  return { text: (data.content || []).filter(c => c.type === 'text').map(c => c.text || '').join('\n').trim(), truncated: data.stop_reason === 'max_tokens',
    usage: { input: u.input_tokens || 0, output: u.output_tokens || 0, cacheRead: u.cache_read_input_tokens || 0, cacheWrite: u.cache_creation_input_tokens || 0 } };
}

function extractJson(raw) {
  const s = String(raw || '').replace(/```(?:json)?/gi, '');
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a === -1 || b <= a) throw new Error('no JSON object in the reply');
  return JSON.parse(s.slice(a, b + 1));
}

// ---- settings read at run time ----
function readText(path, what) {
  if (!existsSync(path)) throw new Error(what + ' not found at ' + path);
  return readFileSync(path, 'utf8');
}
function loadStyle(path = STYLE_PATH) {
  try { const j = JSON.parse(readFileSync(path, 'utf8')); return Array.isArray(j.limits) ? j.limits : []; } catch (_e) { return []; }
}

// ---- the prompt ----
export function buildSystemPrompt({ rules, limits, band, type }) {
  const rationed = limits.length
    ? 'WORDS TO RATION (counted by code in your section text and short description, outside quotations; over the limit and the draft is sent back)\n' +
      limits.map(l => '- "' + l.id + '": at most ' + l.maxPerArticle + ' per article. Instead of the extra uses, vary the wording, for example: ' + (l.instead || []).join(', ') + '.').join('\n') + '\n\n'
    : '';
  return `You are Augustine, the writer for "Catholic Timeline", a reference site on the history of the Catholic Church. You write ONE article, from the numbered sources you are given and from nothing else.

THE SOURCES RULE (absolute)
- Every fact in your article (each date, number, name, place, event and attribution) must come from the sources. Use no outside knowledge, not even for something you are sure of. If the sources do not say it, leave it out.
- Do not copy sentences from a source. Write in your own words. The only copied text is inside quotations, which must be word for word from one source.
- Give each fact the weight the sources give it: where a source says tradition holds, or later legend relates, you say so (the four tiers in the rules below).
- Scripture: refer to a passage and, at most, quote a short verse or two word for word, with the reference. Never reproduce a chapter.

WHEN SOURCES DISAGREE
- You PICK THE WINNER and write only the winning version into the article. Do not write both versions into the text. Prefer the higher-ranked source (a LOWER rank number is higher; see the tier legend). When ranks are equal, prefer the more specific source, then the fuller one. A source speaking for itself about its own subject (an official body on its own matter) wins on that matter.
- Then record the conflict in "reviewNotes" with kind "conflict": the claim, the version you chose and its source number, the other version and its source number, and your reason in one plain sentence. A person makes the final decision, so be exact and honest about what you were unsure of.
- Also add review notes for: a claim that rests on tradition or legend ("tradition"); material that is thin ("thin"); the approval status of an apparition or miracle ("approval"); anything else you are unsure of ("other"). Each note says the real concern, specifically ("Only source for the date is a 1912 encyclopedia; the diocese's own page gives none"), never just "sourcing is thin".

${rationed}HOW TO WRITE (the house rules; follow them exactly)
${rules}

LENGTH: this article is in the "${band.tier}" tier: ${band.min} to ${band.max} words in the sections taken together; never more than ${band.max}. If the sources are too thin to reach ${band.min} honestly, write less and add a "thin" review note; never pad.

THE ENTRY TYPE is ${CATEGORY_LABEL[type] || type}. Use only the Quick Fact labels the rules list for it, and leave out any fact the sources do not give.

AGE AT DEATH (people only): the reader wants to know whether he died old or young. Do NOT work out the age yourself. Write the "Born" and "Died" Quick Facts exactly as the sources give them: month, day and year when the sources give them; "c." before a year that is approximate; a range such as "c. 1020/1025" when the sources give one; the year only when that is all they give. Do not put an age in the "Died" fact; code adds it. In the narrative of his death write the marker [[AGE]] exactly once, where the age belongs, for example: "He died on August 28, 430, [[AGE]], while the Vandals besieged the city." Code replaces the marker with "at the age of seventy-five" or "at about seventy-five", and removes it where no age can be worked out. Do not write any other statement of the age at death.

FORMAT OF THE SECTIONS: plain text only. Paragraphs are separated by a blank line. No HTML except <i> for titles of works. No <p>, no markdown, no entry: links, no footnote numbers.

REPLY WITH ONLY THIS JSON, no preamble, no code fences:
{
 "d": "the short description: one or two sentences",
 "sections": [ { "h": "heading", "b": "paragraph one\\n\\nparagraph two" } ],
 "quotes": [ { "text": "exact words from ONE source", "source": "who said or wrote it, and where (for example Confessions X, 27)" } ],
 "facts": [ { "label": "Feast day", "value": "August 28" } ],
 "country": "the modern country name, or an empty string",
 "region": "one of: ${REGIONS.join(', ')}",
 "alt": [ "other names the subject is known by, if any" ],
 "reviewNotes": [ { "kind": "conflict | tradition | thin | approval | other", "claim": "...", "chosen": { "text": "...", "source": 1 }, "other": { "text": "...", "source": 2 }, "why": "one sentence" } ],
 "flaggedWords": [ "plain names or terms in your article that a text-to-speech voice may mispronounce; the words only, no pronunciation" ],
 "sourceFeedback": { "amount": "too_little | about_right | too_much", "used": [ 1, 2 ], "unused": [ 3 ], "gaps": [ "what the sources did not tell you that the article needed" ], "wouldHelp": [ "what kind of source or material would have made this easier or better" ] }
}
sourceFeedback is for the people who run this process, never for the reader: say honestly whether the sources were too little, about right or too much for this article, which numbered sources you actually drew on, and what was missing or surplus.
For kinds other than "conflict" use { "kind": "...", "note": "the specific concern" }.`;
}

function tierLegend(registry) {
  const t = (registry && registry.tiers) || {};
  return Object.fromEntries(Object.entries(t).map(([k, v]) => [k, { rank: v.rank, label: v.label, means: v.means, canVerify: v.canVerify }]));
}

// ---- turning the model's JSON into a clean draft ----
const str = (v, n = 4000) => (typeof v === 'string' ? v.trim().slice(0, n) : '');

export function normalizeDraft(raw, { type, mode, existing }) {
  const o = raw && typeof raw === 'object' ? raw : {};
  const sections = (Array.isArray(o.sections) ? o.sections : []).map(s => ({ h: str(s && s.h, 200), b: str(s && s.b, 20000).replace(/\r\n/g, '\n').replace(/\n{3,}/g, '\n\n') }));
  const quotes = (Array.isArray(o.quotes) ? o.quotes : []).map(q => ({ text: str(q && q.text, 1500), source: str(q && q.source, 300) }));
  const facts = (Array.isArray(o.facts) ? o.facts : []).map(f => ({ label: str(f && f.label, 80), value: str(f && f.value, 400) }));
  const notes = [];
  for (const n of Array.isArray(o.reviewNotes) ? o.reviewNotes : []) {
    if (!n || typeof n !== 'object') continue;
    const kind = NOTE_KINDS.includes(n.kind) ? n.kind : 'other';
    if (kind === 'conflict') {
      const src = x => { const v = parseInt(x && x.source, 10); return Number.isFinite(v) && v > 0 ? v : null; };
      notes.push({ kind, claim: str(n.claim, 400), chosen: { text: str(n.chosen && n.chosen.text, 400), source: src(n.chosen) }, other: { text: str(n.other && n.other.text, 400), source: src(n.other) }, why: str(n.why, 400) });
    } else notes.push({ kind, note: str(n.note || n.why || n.claim, 600) });
  }
  const regionOk = REGIONS.includes(o.region);
  return {
    d: str(o.d, 600), sections, quotes, facts, country: str(o.country, 60), region: regionOk ? o.region : (existing && existing.r) || '',
    regionGiven: str(o.region, 40), alt: (Array.isArray(o.alt) ? o.alt : []).map(a => str(a, 80)).filter(Boolean).slice(0, 8),
    reviewNotes: notes.filter(n => (n.kind === 'conflict' ? n.claim || n.why : n.note)),
    flaggedWords: [...new Set((Array.isArray(o.flaggedWords) ? o.flaggedWords : []).map(w => str(w, 60)).filter(Boolean))].slice(0, 40),
    sourceFeedback: normalizeFeedback(o.sourceFeedback)
  };
}

const nums = a => [...new Set((Array.isArray(a) ? a : []).map(x => parseInt(x, 10)).filter(n => Number.isFinite(n) && n > 0))].sort((x, y) => x - y);
export function normalizeFeedback(f) {
  if (!f || typeof f !== 'object') return null;
  return { amount: AMOUNTS.includes(f.amount) ? f.amount : null, used: nums(f.used), unused: nums(f.unused),
    gaps: (Array.isArray(f.gaps) ? f.gaps : []).map(g => str(g, 300)).filter(Boolean).slice(0, 8), wouldHelp: (Array.isArray(f.wouldHelp) ? f.wouldHelp : []).map(g => str(g, 300)).filter(Boolean).slice(0, 8) };
}

// The age phrase for the marker: exact ages say "at the age of", estimates say "at about". Words up to a hundred, digits above.
export function agePhrase(lifespan) {
  if (!lifespan || lifespan.age == null) return '';
  const n = lifespan.age < 100 ? numberWords(lifespan.age) : String(lifespan.age);
  return (lifespan.kind === 'exact' ? 'at the age of ' : 'at about ') + n;
}
// Fill or drop the [[AGE]] markers in the sections. Returns the number of markers found.
export function fillAgeMarkers(sections, lifespan) {
  let count = 0;
  const phrase = agePhrase(lifespan);
  for (const s of sections) {
    s.b = String(s.b || '').replace(/(\s*,?\s*)\[\[AGE\]\]/g, (_m, lead) => { count++; return phrase ? lead + phrase : ''; });
  }
  return count;
}

// The sources as the model sees them: numbered in rank order, with the tier legend. Text only goes to the model, never into the draft.
function prepareSources(texts, file, registry) {
  const rankOf = tier => { const t = registry && registry.tiers && registry.tiers[tier]; return t && t.rank != null ? t.rank : 99; };
  const meta = new Map(file.sources.map(s => [s.n, s]));
  return texts.filter(t => t.drift !== 'unavailable' && t.text)
    .map(t => ({ ...t, title: (meta.get(t.n) || {}).title || '', rank: rankOf(t.tier), words: wordCount(t.text), cut: t.text.length > MAX_SOURCE_CHARS, send: t.text.slice(0, MAX_SOURCE_CHARS) }))
    .sort((a, b) => a.rank - b.rank || a.n - b.n)
    .map((t, i) => ({ ...t, num: i + 1 }));
}

function linksFrom(sources) {
  const out = [], skipped = [];
  for (const s of sources) {
    if (/(^|\.)miracolieucaristici\.org$/.test(s.domain)) { skipped.push(s); continue; }       // that link lives in the separate carloLinks table
    const site = String(s.domain || '').replace(/^www\./, '');
    out.push({ label: (site + (s.title ? ': ' + s.title.replace(/\s+/g, ' ').trim().slice(0, 90) : '')).trim(), url: s.url });
  }
  return { links: out, skipped };
}

const sigHash = s => createHash('sha256').update(s).digest('hex').slice(0, 12);

// ---- the run ----
export async function writeDraft(subject, { sourcesDir = SOURCES_DIR, task, now = new Date(), deps = {} } = {}) {
  const t0 = Date.now();
  const p = (task && task.payload) || {};
  const id = entryIdFor(subject);
  const file = loadSources(id, sourcesDir);
  if (!file) return { outcome: 'blocked', reason: 'no sources file for ' + id + ' (run Jerome first)' };
  if (file.outcome !== 'ready' && !p.override) return { outcome: 'blocked', reason: 'Jerome\'s outcome for this entry is "' + file.outcome + '"' + (file.reason ? ' (' + file.reason + ')' : '') + '; a person must decide (resend with override) before anything is written' };

  const registry = deps.registry || (() => { try { return loadRegistry(); } catch (_e) { return null; } })();
  const texts = await getSourceTexts(file, { fetchPage: deps.fetchPage || realFetchPage });
  const sources = prepareSources(texts, file, registry);
  const dropped = texts.filter(t => t.drift === 'unavailable').length;
  const changed = texts.filter(t => t.drift === 'changed').length;
  const sourceWords = sources.reduce((n, s) => n + s.words, 0);
  if (sourceWords < MIN_SOURCE_WORDS) return { outcome: 'blocked', reason: 'only ' + sourceWords + ' words of source text could be read now (' + dropped + ' page(s) could not be fetched); the minimum is ' + MIN_SOURCE_WORDS };

  const type = (file.subject && file.subject.category) || subject.category || 's';
  const band = lengthTier({ requested: p.length, entryTier: subject.tier, sourceWords });
  const limits = deps.limits || loadStyle();
  const rules = deps.rules != null ? deps.rules : readText(RULES_PATH, 'the writer rules');
  const model = p.model || deps.model || DEFAULT_MODEL;
  const system = buildSystemPrompt({ rules, limits, band, type });
  const call = deps.callModel || callAnthropic;

  const base = {
    subject: { name: file.subject.name || subject.name, category: type, year: file.subject.year != null ? file.subject.year : subject.year },
    entryType: CATEGORY_LABEL[type] || type, length: band, tierLegend: tierLegend(registry),
    jeromeNotes: { outcome: file.outcome, flags: file.flags || [], verdict: file.verdict ? { action: file.verdict.action, reasons: (file.verdict.reasons || []).map(r => r.text), advisory: (file.verdict.advisory || []).map(r => r.text) } : null,
      missingPerspectives: (file.perspectives && file.perspectives.missing) || [], diocese: file.authority ? file.authority.diocese : undefined },
    sources: sources.map(s => ({ n: s.num, rank: s.rank, tier: s.tier, domain: s.domain, title: s.title, url: s.url, words: s.words, ...(s.cut ? { note: 'cut after ' + MAX_SOURCE_CHARS + ' characters' } : {}), text: s.send }))
  };

  const attemptLog = [];
  const usageTotal = { role: 'writer', provider: 'anthropic', model, calls: 0, inputTokens: 0, outputTokens: 0, cacheReadTokens: 0, cacheWriteTokens: 0 };
  let draft = null, result = null, previous = null, failure = null;
  const plainSources = sources.map(s => ({ n: s.num, text: s.text }));

  for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
    const user = JSON.stringify({ ...base, ...(failure ? { revise: { instruction: 'Your previous draft broke these rules. Rewrite the whole article so that none is broken, changing as little else as you can.', problems: failure, previousDraft: previous } } : {}) });
    let reply, parsed = null, parseErr = '';
    for (let b = 0; b < TOKEN_BUDGETS.length; b++) {
      reply = await call({ system, user, maxTokens: TOKEN_BUDGETS[b], model });
      usageTotal.calls++; usageTotal.inputTokens += reply.usage.input || 0; usageTotal.outputTokens += reply.usage.output || 0;
      usageTotal.cacheReadTokens += reply.usage.cacheRead || 0; usageTotal.cacheWriteTokens += reply.usage.cacheWrite || 0;
      tokensUsed += (reply.usage.input || 0) + (reply.usage.output || 0);
      if (reply.truncated) { parseErr = 'the reply was cut off at the token limit'; continue; }
      try { parsed = extractJson(reply.text); parseErr = ''; } catch (e) { parseErr = 'the reply was not valid JSON (' + e.message + ')'; }
      break;
    }
    const callUsage = { model, inputTokens: reply ? reply.usage.input : 0, outputTokens: reply ? reply.usage.output : 0 };
    if (!parsed) { failure = [parseErr || 'no usable reply']; attemptLog.push({ n: attempt, violations: failure, usage: callUsage }); continue; }

    draft = normalizeDraft(parsed, { type, mode: file.mode, existing: subject.r ? { r: subject.r } : null });
    // Age at death: code works it out from the Born and Died facts and fills the [[AGE]] marker; the model's own copy (marker and facts as he wrote them) is what he is
    // shown again if the draft is sent back.
    const rawSections = draft.sections.map(x => ({ ...x })), rawFacts = draft.facts.map(x => ({ ...x }));
    const isPerson = type === 's';
    const la = isPerson ? applyAgeToFacts(draft.facts) : { facts: draft.facts, lifespan: { age: null, reason: 'not a person' } };
    draft.facts = la.facts; draft.lifespan = la.lifespan;
    const markers = fillAgeMarkers(draft.sections, la.lifespan);
    result = checkDraft(draft, { type, band, limits, sources: plainSources, sourceWords });
    const extra = [];
    if (!subject.id && !REGIONS.includes(draft.regionGiven)) extra.push({ rule: 'region', text: 'region must be one of: ' + REGIONS.join(', ') });
    if (isPerson && la.lifespan.age != null && markers !== 1) {
      extra.push({ rule: 'age', text: markers === 0 ? 'write the marker ' + AGE_TOKEN + ' once in the narrative of his death (code fills it in as "' + agePhrase(la.lifespan) + '")' : 'write the marker ' + AGE_TOKEN + ' only once; you wrote it ' + markers + ' times' });
    }
    const vs = result.violations.concat(extra);
    attemptLog.push({ n: attempt, violations: vs.map(v => v.text), usage: callUsage });
    if (!vs.length) { result.violations = []; break; }
    result.violations = vs;
    failure = vs.map(v => v.text).slice(0, 14);
    previous = { d: draft.d, sections: rawSections, quotes: draft.quotes, facts: rawFacts };
  }
  if (!draft) return { outcome: 'error', reason: 'the model never returned a usable article: ' + (failure && failure[0]), attemptLog, usage: usageTotal };

  const passed = !!result && result.violations.length === 0;
  const { links, skipped } = linksFrom(sources);
  const quotes = draft.quotes.filter(q => q.text);
  const notes = draft.reviewNotes.map(n => (n.kind === 'conflict'
    ? { ...n, chosen: { ...n.chosen, site: (sources.find(s => s.num === n.chosen.source) || {}).domain }, other: { ...n.other, site: (sources.find(s => s.num === n.other.source) || {}).domain } } : n));

  // Notes added by code, not left to the model: Jerome's own warnings, thin material, a form failure, and the approval note for apparitions and miracles.
  const jn = [];
  if (file.flags && file.flags.length) jn.push('Jerome flagged: ' + file.flags.join(', '));
  if (file.perspectives && file.perspectives.missing && file.perspectives.missing.length) jn.push('no source found for: ' + file.perspectives.missing.join(', '));
  if (changed) jn.push(changed + ' source page(s) differ in length from what Jerome saw');
  if (dropped) jn.push(dropped + ' source page(s) could not be fetched again and were not used');
  if (jn.length) notes.push({ kind: 'sources', note: jn.join('; ') });
  if (skipped.length) notes.push({ kind: 'other', note: skipped.map(s => s.domain).join(', ') + ' was a source but is not linked in the article; that link belongs in the separate carloLinks table' });
  const words = result.stats.words;
  if (words < band.min && !notes.some(n => n.kind === 'thin')) notes.push({ kind: 'thin', note: 'The article is ' + words + ' words, under the ' + band.min + '-word target for the ' + band.tier + ' tier, because the sources give no more to say.' });
  if ((type === 'm' || type === 'u') && !notes.some(n => n.kind === 'approval')) {
    notes.push({ kind: 'approval', note: 'A person must confirm the approval status against the bishop\'s or the Dicastery\'s own statement' + (file.authority && file.authority.diocese ? ' (' + file.authority.diocese + ')' : '') + '. The article states only what the sources state.' });
  }
  const lf = draft.lifespan;                                  // no review note when no age can be given: Tom, 2026-10-09 ("No note needed if age is left out"); the reason stays in draft.lifespan and the log
  if (!passed) notes.push({ kind: 'form', note: 'Still failing after ' + attemptLog.length + ' attempts: ' + result.violations.slice(0, 5).map(v => v.text).join(' | ') });

  const entry = { id, y: subject.y != null ? subject.y : (file.subject.year != null ? file.subject.year : null), n: subject.n || file.subject.name || subject.name, t: type, r: subject.r || draft.region,
    country: draft.country, alt: draft.alt, d: draft.d, art: { sections: draft.sections, quotes, links }, facts: draft.facts };
  const out = {
    version: 1, entryId: id, mode: file.mode, status: passed ? 'draft' : 'needs_work', subject: base.subject, builtAt: now.toISOString(),
    writer: { role: 'Augustine', model, attempts: attemptLog.length, maxAttempts: MAX_ATTEMPTS, rules: sigHash(rules), style: sigHash(JSON.stringify(limits)) },
    sourcesFile: { file: 'sources/' + id + '.json', jobId: file.jobId || null, builtAt: file.builtAt || null, outcome: file.outcome, pages: sources.length, words: sourceWords, dropped, changed },
    length: band, entry, reviewNotes: notes, flaggedWords: draft.flaggedWords,
    lifespan: type === 's' ? { age: lf.age, kind: lf.kind || null, min: lf.min != null ? lf.min : null, max: lf.max != null ? lf.max : null, reason: lf.reason || null, born: lf.bornText || null, died: lf.diedText || null } : null,
    sourceFeedback: draft.sourceFeedback, sourceStats: sources.map(x => ({ n: x.num, jeromeN: x.n, domain: x.domain, tier: x.tier, words: x.words, used: draft.sourceFeedback && draft.sourceFeedback.used.length ? draft.sourceFeedback.used.includes(x.num) : null })),
    checks: { passed, violations: result.violations, stats: result.stats }, attemptLog, usage: [usageTotal], seconds: Math.round((Date.now() - t0) / 100) / 10
  };
  return { outcome: 'written', draft: out };
}

export function writeDraftFile(draft, dir = DRAFTS_DIR) {
  const path = join(dir, draft.entryId + '.json');
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, JSON.stringify(draft, null, 1) + '\n');
  return path;
}

// The orchestrator's handler: (task, dataJson, workLog, deps) => outcome. The third argument is the work log, not dependencies.
export async function runArticleWrite(task, dataJson, _workLog, deps = {}) {
  const p = (task && task.payload) || {};
  tokensUsed = 0;
  let subject;
  if (task.entityId && !p.name) {
    const e = (dataJson.entries || []).find(x => x.id === task.entityId);
    if (!e) return { result: { outcome: 'error', reason: 'no entry with id ' + task.entityId }, summary: 'no entry with id ' + task.entityId };
    subject = { id: e.id, name: e.n, y: e.y, year: e.y, n: e.n, t: e.t, category: e.t, r: e.r, tier: e.tier };
  } else {
    if (!p.name) return { result: { outcome: 'error', reason: 'a new subject needs payload.name' }, summary: 'a new subject needs payload.name' };
    subject = { name: p.name, category: p.category, year: p.year != null ? p.year : null, y: p.year != null ? p.year : null, n: p.name };
  }
  let r;
  try { r = await writeDraft(subject, { sourcesDir: deps.sourcesDir || SOURCES_DIR, task, now: deps.now || new Date(), deps }); }
  catch (err) {
    if (err && err.deferred) throw err;
    return { result: { outcome: 'error', reason: String((err && err.message) || err).slice(0, 300) }, summary: 'error: ' + String((err && err.message) || err).slice(0, 200), provider: 'anthropic', tokensUsed };
  }
  if (r.outcome !== 'written') {
    return { result: { outcome: r.outcome, reason: r.reason }, summary: (r.outcome === 'blocked' ? 'blocked: ' : 'error: ') + r.reason, provider: 'anthropic', tokensUsed };
  }
  const d = r.draft;
  const path = writeDraftFile(d, deps.draftsDir || DRAFTS_DIR);
  const files = [path];
  try { recordWriter({ draft: d, task, logPath: deps.logPath || LOG_PATH, now: deps.now || new Date() }); files.push(deps.logPath || LOG_PATH); } catch (_e) { /* the log is optional */ }
  const st = d.checks.stats;
  return {
    result: { outcome: 'written', entryId: d.entryId, status: d.status, file: path, words: st.words, sections: st.sections, attempts: d.writer.attempts, reviewNotes: d.reviewNotes.length, usage: d.usage, model: d.writer.model },
    summary: (d.status === 'draft' ? 'draft written' : 'draft written but STILL FAILING form checks') + ' for ' + d.subject.name + ': ' + st.words + ' words, ' + st.sections + ' sections, ' + d.reviewNotes.length + ' review note(s), attempt ' + d.writer.attempts,
    provider: 'anthropic', tokensUsed, filesToCommit: files
  };
}

